************************************************************************
*                                                                      *
      subroutine thetreg(ncol,m,nd,ns0,nl,lt,np,nr,mr,kr,
     &                   ne,eb,tr,rabs,trEVENT)
*                                                                      *
*       nuclear heating tally in region mesh                           *
*       last modified by K.Niita on 2011/05/17                         *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              0 : end of batch                                        *
*              4 : source particle                                     *
*                                                                      *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
*     definition of tr( nd, ir, id )                                   *
*                                                                      *
*        ns = 1 : all, 2 : simple, 3 : heat                            *
*                                                                      *
*      nd ..... number of event type                                   *
*        ns = 3                                                        *
*          1 : total                                                   *
*                                                                      *
*        ns = 2                                                        *
*          2 : cutoff neutron                                          *
*          3 : cutoff photon                                           *
*          4 : cutoff proton                                           *
*          5 : leakage                                                 *
*                                                                      *
*          6 : recoil                                                  *
*          7 : ionization                                              *
*          8 : low neutron                                             *
*          9 : photon                                                  *
*         10 : low proton                                              *
*         11 : other                                                   *
*                                                                      *
*        ns = 1                                                        *
*         12 : deuteron recoil                                         *
*         13 : triton   recoil                                         *
*         14 : 3He      recoil                                         *
*         15 : alpha    recoil                                         *
*         16 : residual recoil                                         *
*                                                                      *
*         17 : proton ionization                                       *
*         18 : pion+  ionization                                       *
*         19 : pion-  ionization                                       *
*         20 : other  ionization                                       *
*                                                                      *
*         21 : stopped proton                                          *
*         22 : stopped neutron                                         *
*         23 : stopped photon                                          *
*         24 : stopped pion+                                           *
*         25 : stopped pion-                                           *
*         26 : stopped other                                           *
*                                                                      *
*         27 : remaining excitation energy                             *
*         28 : fission high recoil                                     *
*         29 : fission low neutron                                     *
*                                                                      *
*         29 + np      : ionization of other paticle                   *
*         29 + np + np : stopped other paticle                         *
*                                                                      *
*       id ..... data type                                             *
*          1 : heating                                                 *
*          2 : relative error                                          *
*                                                                      *
*       unit = MeV                                                     *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use NGSDATAMOD, only : bindeg
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
*-----------------------------------------------------------------------

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)
      common /mathzn/ mathz, mathn, jcoll, kcoll
!$OMP THREADPRIVATE(/mathzn/)
      common /regdc/  idrg(kvlmax), idgr(kvmmax)
      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)
      common /eparm/  esmax, esmin, emin(20)
      common /celdn/  denr(kvlmax), denm(kvlmax), denc(kvlmax)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall32/ itelc(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall82/ itcnth(9,itlmax)

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   kr(mr)
      dimension   tr(nd,nr,0:ne,2)
      dimension   trEVENT(nd,nr,0:ne)       !OBINATA(2012.7.23): as Ct
      real(8),allocatable,save:: tr0(:,:,:) !OBINATA(2012.7.23): as C
      dimension   rabs(5)
      dimension   eb(ne+1)

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt

*-----------------------------------------------------------------------

      data rmngv / 0.93895 /
      data rmnmv / 938.95 /

      save sweight
!$OMP THREADPRIVATE(sweight)
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /tall36/ itdpo(itlmax)

*-----------------------------------------------------------------------
      common /dedxfac/ dedxfd
!$OMP THREADPRIVATE(/dedxfac/)

*-----------------------------------------------------------------------

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas

*-----------------------------------------------------------------------
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /celdg/  rhog(kvlmax)

*-----------------------------------------------------------------------

      real*8 edep
      common/EPCONTedep/ edep
!$OMP THREADPRIVATE(/EPCONTedep/)

      integer iegsemi, iegsout
      common /egsemi/ iegsemi, iegsout

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

      real(8),pointer:: tr_sum(:)

*-----------------------------------------------------------------------
*     ns from ns0
*-----------------------------------------------------------------------

            ns = ns0
            if( ns .ge. 4 ) ns = ns - 3

*-----------------------------------------------------------------------
*     deposit : ncol = 0, 4 and ns = 4
*-----------------------------------------------------------------------

      if( ( ncol .eq. 0 .or. ncol .eq. 4 ) .and. ns0 .ge. 4 ) then

         if( nocas .gt. 1 .or. ncol .eq. 0 ) then

            do id = 1, nd
            do ir = 1, nr

               if( itdpo(m) .eq. 0 .and. trEVENT(1,ir,0) .gt. 0.0 ) then

                  heats = trEVENT(1,ir,0)
                  ratio = trEVENT(id,ir,0) / trEVENT(1,ir,0)

               else

                  heats = trEVENT(id,ir,0)
                  ratio = 1.0d0

               end if

               if( heats .gt. 0.0d0 .and.
     &             heats .ge. eb(1) .and. heats .lt. eb(ne+1) ) then

                  do ie = 1, ne

                     if( heats .ge. eb(ie) .and.
     &                   heats .lt. eb(ie+1) ) then

                        trEVENT(id,ir,ie) = trEVENT(id,ir,ie)
     &                                    + sweight*ratio

                     end if

                  end do

               end if

            end do
            end do

         end if

*-----------------------------------------------------------------------
*        save initial weight and zero set
*-----------------------------------------------------------------------

         if( ncol .eq. 4 ) then

            sweight = oldwt

            do id = 1, nd
            do ir = 1, nr
            do ik = 1, 2

               trEVENT(id,ir,0) = 0.0d0

            end do
            end do
            end do

         end if

      end if

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.7.23): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,1) = tr(:,:,:,1) + trEVENT(:,:,:)
             tr(:,:,:,2) = tr(:,:,:,2) + trEVENT(:,:,:) ** 2

! sumover
             call thetreg_sumover(m,1,
     &                   nd,    nr,    ne,    trEVENT)

           end if

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.7.23): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(nd,nr,0:ne) )
             tr0(:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (thetreg_crit_ist1)
             tr0(:,:,:) = tr0(:,:,:) + trEVENT(:,:,:)
!$OMP END CRITICAL (thetreg_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,1) = tr(:,:,:,1) + tr0(:,:,:) / maxcas
             tr(:,:,:,2) = tr(:,:,:,2)
     &                   + ( tr0(:,:,:) / maxcas ) ** 2

! sumover
             call thetreg_sumover(m,maxcas,
     &                   nd,    nr,    ne,    tr0)

! sumover

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*     check of ncol
*-----------------------------------------------------------------------

      if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------
*        itelc(m)=0: nothing for electron and positron and
*                    secondary photon by nuclear data
*-----------------------------------------------------------------------

         if( itelc(m) .eq. 0 .and. iegsemi .eq. 0 .and.
     &     ( jcoll .eq. 8 .or.
     &     ( ( jcoll .eq. 7 .or. jcoll .eq. 15 ) .and.
     &       name(ibknam+no,ipomp+1) .gt. 1 ) ) ) return

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        incident particle energy loss
*-----------------------------------------------------------------------
*        enmin : final particle energy ( with mass for not nucleon )
*        enion : ionization loss energy for charged particles
*-----------------------------------------------------------------------

               if( ityp .le. 2 .or. ityp .ge. 12 ) then
                  enmin = 0.0
               else
                  enmin = rtyp - mtyp * rmnmv
               end if

               enmin = ( ec(ibkec+no,ipomp+1) + enmin ) * oldwt
               enion = abs( ec(ibkec+no,ipomp+1) -
     &                             e(ibke+no,ipomp+1) ) * oldwt

*-----------------------------------------------------------------------
cKN Iwase 2014/08/29 for EGS, delete by T.Sato only for photon 2016/02/01

               if( ( ityp.eq.12 .or. ityp.eq.13 ) .and.
     &               iegsemi .ne. 0 ) then

                     enion = edep * oldwt

                  if(ncol.eq.9 .or. ncol.eq.11) then
                     enmin = enmin + edep * oldwt
                     enion = 0d0
                  endif

               endif

*-----------------------------------------------------------------------

                  enmin0 = enmin
                  enion0 = enion

               if( itunt(m) .eq. 0 .and. mat .gt. 0 ) then
                  enmin = enmin / rhog(mat)
                  enion = enion / rhog(mat)
               end if

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

               jj = 0

*-----------------------------------------------------------------------

      do 100 ii = 1, nr

*-----------------------------------------------------------------------

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 100

               ir = ii

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &              goto 200

               end if

            end do

*-----------------------------------------------------------------------
*        ionization
*-----------------------------------------------------------------------

            if( enion .gt. 0.0 ) then

                         trEVENT(1,ir,0) = trEVENT(1,ir,0) + enion

               if( ns .le. 2 ) then

                         trEVENT(7,ir,0) = trEVENT(7,ir,0) + enion
               end if

               if( ns .eq. 1 ) then
                  if( ityp .eq. 1 ) then
                        k = 17
                  else if( ityp .eq. 3 ) then
                        k = 18
                  else if( ityp .eq. 5 ) then
                        k = 19
                  else if( ityp .eq. 12 .or. ityp .eq. 13 ) then
                        k = 20
                        rabs(4) = rabs(4) + enion0
                  else
                        k = 20
                  end if
                         trEVENT(k,ir,0) = trEVENT(k,ir,0) + enion
                  if( np .gt. 0 ) then
                        call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)
                     if( ipn .gt. 0 ) then

                        do i = 1, ipn
                           k = 29 + ips(i)
                           trEVENT(k,ir,0) = trEVENT(k,ir,0) + enion
                        end do

                     end if
                  end if
               end if

            end if

*-----------------------------------------------------------------------
*        stopped energy cut-off or time cut-off particles
*-----------------------------------------------------------------------

            if( ncol .eq. 9 .or. ncol .eq. 11 ) then

                         trEVENT(1,ir,0) = trEVENT(1,ir,0) + enmin

               if( ns .le. 2 ) then

                  if( ityp .ne. 12 .and. ityp .ne. 13 ) then

                         trEVENT(11,ir,0) = trEVENT(11,ir,0) + enmin

                  else

                         trEVENT(9,ir,0) = trEVENT(9,ir,0) + enmin

                  end if

               end if

               if( ns .eq. 1 ) then
                  if( ityp .eq. 1 ) then
                        k = 21
                  else if( ityp .eq. 3 ) then
                        k = 24
                  else if( ityp .eq. 5 ) then
                        k = 25
                  else if( ityp .eq. 12 .or. ityp .eq. 13 ) then
                        k = 26
                        rabs(4) = rabs(4) + enmin0
                  else
                        k = 26
                  end if

                        trEVENT(k,ir,0) = trEVENT(k,ir,0) + enmin

                  if( np .gt. 0 ) then
                     call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)
                     if( ipn .gt. 0 ) then

                        do i = 1, ipn
                           k = 29 + np + ips(i)
                           trEVENT(k,ir,0) = trEVENT(k,ir,0) + enmin
                        end do

                     end if
                  end if
               end if
            end if

*-----------------------------------------------------------------------
*        termination by escape or leakage
*-----------------------------------------------------------------------

            if( ncol .eq. 12 ) then

               if( ns .le. 2 ) then

                        trEVENT(5,ir,0) = trEVENT(5,ir,0) + enmin

               end if

            end if

*-----------------------------------------------------------------------
*        neutron, proton, and photon for nuclear data
*-----------------------------------------------------------------------

         if( mat .gt. 0 .and.
     &     (  jcoll .eq. 6 .or. jcoll .eq. 9 .or.
     &    ( ( jcoll .eq. 7 .or.
     &      ( jcoll .eq. 15 .and. iegsemi .eq. 0 ) ) .and.
     &        itelc(m) .eq. 0 .and.
     &        name(ibknam+no,ipomp+1) .eq. 1 ) ) ) then

*-----------------------------------------------------------------------

            icl = idgr(iblz1)
            erg = ( e(ibke+no,ipomp+1) + ec(ibkec+no,ipomp+1) ) / 2.0
            tgt = sqrt( ( xc(ibkxc+no,ipomp+1) - x(ibkx+no,ipomp+1) )**2
     &                + ( yc(ibkyc+no,ipomp+1) - y(ibky+no,ipomp+1) )**2
     &                + ( zc(ibkzc+no,ipomp+1)-z(ibkz+no,ipomp+1) )**2 )

               mk = mat
               rh = denm(mat)

               heatr = 0.0
               heatf = 0.0

            if( ityp .eq. 2 ) then

               call heatn(icl,erg,heatr,heatf,mk,rh,m,0,mtdum)

            else if( ityp .eq. 14 ) then

               call heatp(icl,erg,heatr,mk,rh,m,0,mtdum)

               heatf = 0.0

            else if( ityp .eq. 1 ) then

               call heath(icl,erg,heatr,mk,rh,m,0,mtdum)

               heatf = 0.0

            end if

            heatr = heatr * tgt * oldwt
            heatf = heatf * tgt * oldwt
            heat  = heatr + heatf

            heatf0 = heatf
            heat0 = heat

            if( itunt(m) .eq. 0 .and. mat .gt. 0 ) then
              heatf = heatf / rhog(mat)
              heat  = heat / rhog(mat)
            end if

*-----------------------------------------------------------------------

                        trEVENT(1,ir,0) = trEVENT(1,ir,0) + heat

                  if( ns .le. 2 ) then

                     if( ityp .eq. 2 ) then

                        trEVENT(8,ir,0) = trEVENT(8,ir,0) + heat

                     else if( ityp .eq. 1 ) then

                        trEVENT(10,ir,0) = trEVENT(10,ir,0) + heat

                     else

                        trEVENT(9,ir,0) = trEVENT(9,ir,0) + heat

                     end if

                  end if

                  if( ns .eq. 1 ) then

                        trEVENT(29,ir,0) = trEVENT(29,ir,0) + heatf

                  end if

                  if( ityp .eq. 2 ) then
                        rabs(3) = rabs(3) + heat0

                  else if( ityp .eq. 1 ) then
                        rabs(5) = rabs(5) + heat0

                  else
                        rabs(4) = rabs(4) + heat0

                  end if

*-----------------------------------------------------------------------

         end if

*-----------------------------------------------------------------------

  200 continue

*-----------------------------------------------------------------------
*     energy of produced particle and/or nucleus from nuclear reactions
*-----------------------------------------------------------------------
cc H.Iwase 2014/1/9  (for EGS5)

      if( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &    ( mat .gt. 0 .and. nclsts .gt. 0 ) .and.
     &    ( jcoll .lt. 6  .or.
     &    ( jcoll .ge. 10 .and. jcoll .le. 17 ) .or.  ! S.Abe 2017/01/17
     &    ( itelc(m) .eq. 1 .and.
     &    ( jcoll .eq. 7 .or. jcoll .eq. 8 ) ) ) ) then

*-----------------------------------------------------------------------
*           binding energy of nucleus
*-----------------------------------------------------------------------

                  totout = 0.0
                  totmas = 0.0

                  emathi = bindeg(mathz,mathn)

               if( ityp .ge. 15 .and. ityp .le. 19 ) then

                  ipnm = ktyp / 1000000
                  innm = ktyp - ktyp / 1000000 * 1000000 - ipnm

                  emathi = emathi + bindeg(ipnm,innm)

               end if

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                jcount(i,1) .gt. itcnt(i*2+3,m) ) goto 300

               end if

            end do

*-----------------------------------------------------------------------

            do j = 1, nclsts

                  ipart = jclusts(3,j)
                  kpart = jclusts(7,j)
                  jpart = jclusts(5,j)

*-----------------------------------------------------------------------
*              information of nuclei
*              enrem is remaining excitation energies,
*-----------------------------------------------------------------------

               if( ipart .ge. 15 .and. ipart .le. 19 ) then

                     enrem  = qclusts(6,j) * qclusts(8,j)
                     enrem0 = enrem

                     if( itunt(m) .eq. 0 .and. mat .gt. 0 ) then
                       enrem = enrem / rhog(mat)
                     end if

                     totout = totout + enrem0
                     totmas = totmas + bindeg(jclusts(1,j),jclusts(2,j))

*-----------------------------------------------------------------------
*                 enrem is remaining excitation energies,
*-----------------------------------------------------------------------

                        trEVENT(1,ir,0) = trEVENT(1,ir,0) + enrem

                  if( ns .le. 2 ) then

                        trEVENT(11,ir,0) = trEVENT(11,ir,0) + enrem

                  end if

                  if( ns .eq. 1 ) then

                        trEVENT(27,ir,0) = trEVENT(27,ir,0) + enrem

                     if( kcoll .eq. 1 ) then

                        trEVENT(28,ir,0) = trEVENT(28,ir,0) + enrem

                     end if

                  end if

               end if

*-----------------------------------------------------------------------
*              out going particles and nuclei
*-----------------------------------------------------------------------

                  if( ipart .le. 2 .or. ipart .ge. 12 ) then
                     enoms = 0.0
                  else
                     enoms = ( qclusts(5,j) - jclusts(6,j) * rmngv )
                  end if

                     enout = qclusts(7,j)
                     enmas = enoms * 1000.0
                     enpar = ( enout + enmas ) * qclusts(8,j)
                     enpar0 = enpar

                     if( itunt(m) .eq. 0 .and. mat .gt. 0 ) then
                       enpar = enpar / rhog(mat)
                     end if

                     totout = totout + enpar0

*-----------------------------------------------------------------------
*              dead particle and nucleus
*-----------------------------------------------------------------------

               if( jclusts(4,j) .lt. 0 ) then

                     if( jclusts(4,j) .eq. -1 ) then
                        trEVENT(1,ir,0) = trEVENT(1,ir,0) + enpar
                     end if

                  if( ns .le. 2 ) then
                     if( ipart .eq. 2 .and.
     &                   jclusts(4,j) .eq. -2 ) then
                        k = 2
                     else if( ipart .ge. 12 .and. ipart .le. 14 .and.
     &                        jclusts(4,j) .eq. -2 ) then
                        k = 3
                     else if( ipart .eq. 1 .and.
     &                        jclusts(4,j) .eq. -2 ) then
                        k = 4
                     else if( ipart .ge. 15 .and. ipart .le. 19 ) then
                        k = 6
                     else if( ipart .eq. 12 .or. ipart .eq. 13 ) then
                        k = 9
                        rabs(4) = rabs(4) + enpar0
                     else if( ipart .eq. 14 .and. ns .eq. 2 ) then
                        k = 11
                     else if( ipart .eq. 14 .and. ns .eq. 1 ) then
                        k = 0
                     else
                        k = 11
                     end if

                     if( k .gt. 0 ) then
                        trEVENT(k,ir,0) = trEVENT(k,ir,0) + enpar
                     end if
                  end if

                  if( ns .eq. 1 .and. jclusts(4,j) .eq. -1 ) then
                     if( ipart .eq. 1 ) then
                        k = 21
                     else if( ipart .eq. 2 ) then
                        k = 22
                     else if( ipart .eq. 14 ) then
                        k = 23
                     else if( ipart .ge. 15 .and.
     &                        ipart .le. 19) then
                        k = ipart - 3
                     else if( ipart .eq. 3 ) then
                        k = 24
                     else if( ipart .eq. 5 ) then
                        k = 25
                     else if( ipart .ge. 12 .and. ipart .le. 13 ) then
                        k = 26
                     else
                        k = 26
                     end if

                     if( k .gt. 0 ) then
                        trEVENT(k,ir,0) = trEVENT(k,ir,0) + enpar
                     end if

                     if( np .gt. 0 ) then
                           call pcheck(m,np,ipart,kpart,jpart,ipn,ips)
                        if( ipn .gt. 0 ) then
                           do i = 1, ipn
                              k = 29 + np + ips(i)
                              trEVENT(k,ir,0) = trEVENT(k,ir,0) + enpar
                           end do
                        end if
                     end if

                     if( kcoll .eq. 1 ) then
                           trEVENT(28,ir,0) = trEVENT(28,ir,0) + enpar
                     end if
                  end if

               end if

*-----------------------------------------------------------------------

            end do

  300       continue

*-----------------------------------------------------------------------
*        total absorption energy
*-----------------------------------------------------------------------

         if( jcoll .lt.  6 .or. jcoll .eq. 10 .or.
     &       jcoll .eq. 12 .or. jcoll .eq. 16 .or. jcoll .eq. 17 .or.   ! S.Abe 2017/01/17
     &       jcoll .eq. 13 .or. jcoll .eq. 14 .or. jcoll .eq. 15 .or.   ! S.Abe 2017/01/17
     &       jcoll .eq. 11 ) then

            rabs(1) = rabs(1) + enmin0 - totout
            rabs(2) = rabs(2) + ( emathi - totmas ) * oldwt

*-----------------------------------------------------------------------
*           debug for energy conservation
*-----------------------------------------------------------------------




         end if

*-----------------------------------------------------------------------

      end if

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine phetreg(m,nd,ns,np,nr,mr,kr,ne,eb,tr,
     &                   rabs,nvl,ivl,rvl,
     &                   nx,ny,nz,xm,ym,zm,igsh,idasa)
*                                                                      *
*       output the heat tally in region mesh                           *
*       last modified by K.Niita on 2004/09/15                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall49/ itglt(itlmax)

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31
*-----------------------------------------------------------------------

      common /volreg/ dvol(kvlmax)
      common /regdc/ idrg(kvlmax), idgr(kvmmax)
      common /inpec/ ititl, ipara, ibody, iregn, llarr, itby, itar

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)


      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   vl(nr)
      dimension   lr(nr)
      dimension   eb(ne+1)
      dimension   tr(nd,nr,0:ne,2)
      dimension   rabs(5)
      dimension   ivl(nvl)
      dimension   rvl(nvl)
      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   val(nr)

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------
      real(8) cfac
      real(8),parameter:: c2gy=1.602d-10

      dimension tott(max(7,np+1),2) ! frtati 2022/10/20 np+1 -> max(7,np+1)

      character hsunit(0:2)*17
      data hsunit( 0) / '[Gy/source]      '/
      data hsunit( 1) / '[MeV/cm^3/source]'/
      data hsunit( 2) / '[MeV/source]     '/

      character cha*1
      data cha /"'"/

cfrtati 2021/10/05 chl, chm moved to partmod

cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31


      dimension kl(7,7)
      dimension ks(7)

      data ks / 1, 5, 7, 6, 5, 6, 3/
      data ( kl(1,i),i=1,1) /1/
      data ( kl(2,i),i=1,5) /1,2,3,4,5/
      data ( kl(3,i),i=1,7) /1,6,7,8,9,10,11/
      data ( kl(4,i),i=1,6) /6,12,13,14,15,16/
      data ( kl(5,i),i=1,5) /7,17,18,19,20/
      data ( kl(6,i),i=1,6) /21,22,23,24,25,26/
      data ( kl(7,i),i=1,3) /27,28,29/

      character rpa*1
      data rpa /'}'/
      character yen*1

      character cht(7)*10
      data cht /'total heat','recoil    ','ionization',
     &          'low neutrn','photon    ','low proton','others    '/

! sumovver
      maxtott  = max(7,np+1)

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*           itunt(m) = 0 ; cfac = c2gy
*-----------------------------------------------------------------------
            if( itunt(m) .eq. 0)then
              cfac = c2gy
            else
              cfac = 1.0d0
            endif

*-----------------------------------------------------------------------
*        initialization
*-----------------------------------------------------------------------
            if( ns .eq. 3 .or. ns .eq. 6 ) then

               ids = 1
               idf = 1
               idw = 1

            else if( ns .eq. 2 .or. ns .eq. 5 ) then

               ids = 2
               idf = 3
               idw = 7

            else if( ns .eq. 1 .or. ns .eq. 4 ) then

               ids = 2
               idf = 7
               idw = 7

            end if

            if( igsh .ne. 0 ) idw = 1

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

               vl_sum = sum(vl(1:nr))

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

                  c1 = 1.0d+0 / rsouin

               else

                  c1 = 0d0

               end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do ir = 1, nr
               do ik = 1, nd
               do ie = 0, ne

                  if( tr(ik,ir,ie,1) .gt. 0.d0 ) then

                     fmaxfc = tr(ik,ir,ie,1) / vl(ir)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

               end do
               end do
               end do

            end if

            do ir = 1, nr
            do ik = 1, nd
            do ie = 0, ne

               if( tr(ik,ir,ie,1) .gt. 0.d0 ) then

                  call calc_heat_stdev(m,Xa,sigx,
     &                            tr(ik,ir,ie,1), tr(ik,ir,ie,2),
     &                            abs(rtfac(m)/facmax(m))/vl(ir))
                  tr(ik,ir,ie,1) = cfac*Xa
                  tr(ik,ir,ie,2) = sigx

                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ik,ir,ie,1) .gt. cmax ) cmax = tr(ik,ir,ie,1)

                  if( tr(ik,ir,ie,1) .lt. cmin ) cmin = tr(ik,ir,ie,1)

               else

                  isdz = 1
                  tr(ik,ir,ie,2) = 0.0

               end if

! sumover
               fact_in = abs(rtfac(m)/facmax(m))
               call phetreg_sumover_stdev(0,m,ik,ir,ie,
     &                           fact_in,vl(ir),vl_sum)

            end do
            end do
            end do

            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

         end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

         if( igsh .ne. 0 .and.
     &     ( itaxs(m,iax) .lt. 7 .or. itrsh(m) .eq. 0 ) ) goto 900

         if( (itall .eq. 2 .and. nobch .lt. maxbch .and. igsh .eq. 0)
     &        .or. ( itall .eq. 4 .and. igsh .eq. 0 ) ) then

            call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &           nobch,maxbch,npe)

         else

            fname = ctfln(m,iax)

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------
            gfnam = ctfln(m,iax)
            igfmn = itfll(m,iax)
            igser = itger(m)

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

               call thetech(iot,m,iax,1)

*-----------------------------------------------------------------------
*        eng axis for deposit energy distributioon
*-----------------------------------------------------------------------

         if( itaxs(m,iax) .eq. 1 ) then

               inum = 0

               totht = 0.0

            do ir = 1, nr

               inum = inum + 1

               ireg = lr(ir)

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               write(iot,'("#   no. =",i3,3x,"reg =",i7)')
     &                     inum, ireg

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn

*-----------------------------------------------------------------------

               if( ns .eq. 6 ) then

                  write(iot,'( "p: afac(0.8) form(0.9)")')

               else if( ns .eq. 5 ) then

                  write(iot,'( "p: scal(0.5) xorg(0.1) yorg(0.65)")')

               else if( ns .eq. 4 ) then

                  write(iot,'( "p: scal(0.5) xorg(0.1) yorg(1.37)")')

               end if

*-----------------------------------------------------------------------

            do idd = ids, idf

*-----------------------------------------------------------------------

               if( idd .eq. 1 ) then

                  write(iot,'(
     &            "#----------------------------------------#"/
     &            "# Total heat without ncut, gcut and pcut #"/
     &            "#----------------------------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  without ncut"/
     &                        "  gcut and pcut"/
     &                        "e:")')
     &                        yen

               else if( idd .eq. 2 ) then

                  write(iot,'( "p: afac(0.8) form(0.9)")')

                  write(iot,'(
     &            "#-------------------------------------",
     &            "---------#"/
     &            "# Total heat with ncut, gcut, pcut and",
     &            " leakage #"/
     &            "#-------------------------------------",
     &            "---------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  add ncut"/
     &                        "  gcut and pcut"/
     &                        "  and leakage"/
     &                        "e:")')
     &                        yen

               else if( idd .eq. 3 ) then

                  write(iot,'(/"z: xorg(1.8)")')

                  write(iot,'( "p: afac(0.8) form(0.9)")')

                  write(iot,'(
     &            "#---------------------------------------------",
     &            "--------------------------------------------#"/
     &            "# Total heat is the sum of recoil, ionization,",
     &            " low neutron, photon, low proton and others #"/
     &            "#---------------------------------------------",
     &            "--------------------------------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  components of"/
     &                        "  recoil, ionization,"/
     &                        "  low neutron, photon"/
     &                        "  low proton"/
     &                        "  and others"/
     &                        "e:")')
     &                        yen

               else if( idd .eq. 4 ) then

                  write(iot,'(/"z: xorg(-1.8) yorg(-1.37)")')

                  write(iot,'( "p: afac(0.8) form(0.9)")')

                  write(iot,'(
     &            "#------------------------------------------",
     &            "---------#"/
     &            "# Recoil is the sum of d, t, 3He, alpha and",
     &            " residue #"/
     &            "#------------------------------------------",
     &            "---------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  recoil of"/
     &                        "  d, t, 3He, alpha"/
     &                        "  and residue"/
     &                        "e:")')
     &                        yen

               else if( idd .eq. 5 ) then

                  write(iot,'(/"z: xorg(1.8)")')

                  write(iot,'( "p: afac(0.8) form(0.9)")')

                  write(iot,'(
     &            "#----------------------------------------",
     &            "------------------#"/
     &            "# Ionization is the sum of proton, pion+,",
     &            " pion- and others #"/
     &            "#----------------------------------------",
     &            "------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  ionization by"/
     &                        "  proton, pion+-"/
     &                        "  and others"/
     &                        "e:")')
     &                        yen

               else if( idd .eq. 6 ) then

                  write(iot,'(/
     &            "#---------------------------------------#"/
     &            "# Stopped particles of proton, neutron, #"/
     &            "#         photon, pion+- and others     #"/
     &            "#---------------------------------------#"/
     &            )')

               else if( idd .eq. 7 ) then

                  write(iot,'(/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            "# Remaining excitation and Fission high",
     &            " energy recoil and low energy Fission #"/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            )')

               end if

*-----------------------------------------------------------------------

               if( idd .le. 5 ) then

                     write(iot,'(/a1,"no. =",i3,
     &                            ",    reg  =",i7,a1)')
     &                           cha, inum, ireg, cha

                  write(iot,'(/"x: Deposit Energy [MeV]")')
                  write(iot,'( "y: Number [1/source]")')

                  if( itety(m) .eq. 3 .or. itety(m) .eq. 5 ) then

                     write(iot,'( "p: xlog ylog")')

                  else

                     write(iot,'( "p: xlin ylog")')

                  end if

                  if( itanl(m) .gt. 0 ) then

                    write(iot,'( "p: ",200a1)')
     &                         ( itang(m)(i:i),i = 1, itanl(m) )

                  end if

                  if( itsans(m) .gt. 0 ) then

                    call write_sangel(iot,m,0)

                  end if

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 1 ) then

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "h: n",12x,"x",9x,
     &                         "   y(total),hh0l n   ")')

                 else

                  write(iot,'( "h: n",12x,"x",9x,
     &                         "   y1(total),hh0l ny2 dy1=[y1*y2]")')

                 end if

                  write(iot,'( "#  e-lower      e-upper",3x,
     &                         "   total       r.err ")')

               else if( idd .eq. 2 ) then

                  write(iot,'( "h: n",12x,"x",9x,
     &                         "   y(total),hh0l n   ",
     &                         "   y(ncut),hh0dr n   ",
     &                         "   y(pcut),hh0ub n   ",
     &                         "   y(gcut),hh0mg n   ",
     &                         "   y(lekage),hh0qrr n")')

                  write(iot,'( "#  e-lower      e-upper",3x,
     &                         "    total      r.err ",
     &                         "    ncut       r.err ",
     &                         "    pcut       r.err ",
     &                         "    gcut       r.err ",
     &                         "    leakage    r.err ")')

               else if( idd .eq. 3 ) then

                  write(iot,'( "h: n",12x,"x",9x,
     &                         "   y(total),hh0l n   ",
     &                         "   y(recoil),hh0dr n ",
     &                         " y(ionization),hh0ub n",
     &                         " y(low neutron),hh0mg n",
     &                         " y(photon),hh0qrr n  ",
     &                         " y(low proton),hh0vbb n",
     &                         "   y(others),hh0pccc n ")')

                  write(iot,'( "#  e-lower      e-upper",3x,
     &                         "   total       r.err ",
     &                         "   recoil      r.err ",
     &                         "   ionization  r.err ",
     &                         "   low neutron r.err ",
     &                         "   photon      r.err ",
     &                         "   low proton  r.err ",
     &                         "   others      r.err ")')

               else if( idd .eq. 4 ) then

                  write(iot,'( "h: n",12x,"x",9x,
     &                         "   y(recoil),hh0l n  ",
     &                         " y(deuteron),hh0dr n ",
     &                         "   y(triton),hh0ub n ",
     &                         "   y(3He),hh0mg n    ",
     &                         "   y(alpha),hh0qrr n ",
     &                         " y(residue),hh0vbb n ")')

                  write(iot,'( "#  e-lower      e-upper",3x,
     &                         "   recoil      r.err ",
     &                         "   deuteron    r.err ",
     &                         "   triton      r.err ",
     &                         "   3He         r.err ",
     &                         "   alpha       r.err ",
     &                         "   residue     r.err ")')

               else if( idd .eq. 5 ) then

                  write(iot,'( "h: n",12x,"x",9x,
     &                         " y(ionization),hh0l n",
     &                         "   y(proton),hh0dr n ",
     &                         "   y(pion+),hh0ub n  ",
     &                         "   y(pioin-),hh0mg n ",
     &                         "   y(others),hh0qrr n")')

                  write(iot,'( "#  e-lower      e-upper",3x,
     &                         "    ionization r.err ",
     &                         "    proton     r.err ",
     &                         "    pion+      r.err ",
     &                         "    pion-      r.err ",
     &                         "    others     r.err ")')

               else if( idd .eq. 6 ) then

                  write(iot,'( "n: n",12x,"x",10x,
     &                         "  ny1(stop proton) n ",
     &                         "  ny2(stp neutron) n ",
     &                         "  ny3(stop photon) n ",
     &                         "  ny4(stop  pion+) n ",
     &                         "  ny5(stop  pion-) n ",
     &                         "  ny6(stop others) n")')

                  write(iot,'( "#  e-lower      e-upper",4x,
     &                         "  stop proton r.err  ",
     &                         "  stp neutron r.err  ",
     &                         "  stop photon r.err  ",
     &                         "  stop  pion+ r.err  ",
     &                         "  stop  pion- r.err  ",
     &                         "  stop others r.err  ")')

               else if( idd .eq. 7 ) then

                  write(iot,'( "n: n",12x,"x",9x,
     &                         "  ny1(rem. excit.) n ",
     &                         "  ny2(fision high) n ",
     &                         "  ny3(fission low) n")')

                  write(iot,'( "#  e-lower      e-upper",3x,
     &                         "  rem.excit.  r.err  ",
     &                         "  fision high r.err  ",
     &                         "  fission low r.err  ")')

               end if

*-----------------------------------------------------------------------

                  do k = 1, ks(idd)
                        tott(k,1) = 0.d+0
                  end do

                  do ie = 1, ne

                     write(iot,'(1p2e13.4,7(1pe13.4,0pf8.4))')
     &                     eb(ie),eb(ie+1),
     &                     ((tr(kl(idd,k),ir,ie,j),j=1,2),k=1,ks(idd))

                     do k = 1, ks(idd)
                        tott(k,1) = tott(k,1) + tr(kl(idd,k),ir,ie,1)
                     end do

                  end do

! sumover
                  itype_het = 1
                  call phetreg_sumover_get(m,iax,
     &             kl,ks,np,itype_het,             ! itype = 1,2,3
     &             idd,ir,1,maxtott,tott)         ! ie = 1 or ir =1 ,ie=0

                  write(iot,'(/"#   sum over",14x,
     &                        7(1pe13.4,0pf8.4))')
     &                        (tott(k,1),tott(k,2),k=1,ks(idd))

                  write(iot,'(/"#   no. =",i3)') inum

*-----------------------------------------------------------------------

               if( idd .eq. 5 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------#"/
     &            "# Ionization of each particle (group) #"/
     &            "#-------------------------------------#"
     &            )')

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'(/"n: n",12x,"x",12x,
     &                       "n1(total),l3 n ",6x,
     &                       1000(a10,"),hh0",a3," n "))')
     &                        ( chp(i), chl(i) , i = 1, np_mxang ) ! frtati 2021/10/05 np -> np_mxang

                 else

                  write(iot,'(/"n: n",12x,"x",12x,
     &                      "n1(total),l3 n ",6x,
     &         1000(a1,i0,a9,"),hh0",a3
     &         ," ny",i0," dy",i0,"=[y",i0,"*y",i0,"] "))')
     &         ( chp(i)(1:1),i,chp(i)(2:10), chl(i)
     &         ,i+np_mxang,i,i,i+np_mxang, i = 1, np_mxang ) ! frtati 2021/10/05

                 end if

                  write(iot,'( "#  e-lower      e-upper",3x,
     &                         "   ionization r.err  ",
     &                    1000(a1,"  ",a8,"    r.err "))')
     &                    ( chb(i), chp(i)(3:10), i = 1, np ) ! frtati 2021/10/05

                  do k = 1, np
                        tott(k+1,1) = 0.d+0
                  end do

                  do ie = 1, ne

                     write(iot,'(1p2e13.4,1000(1pe13.4,0pf8.4))')
     &                     eb(ie),eb(ie+1),
     &                     (tr(7,ir,ie,j),j=1,2),
     &                     ((tr(29+k,ir,ie,j),j=1,2),k=1,np) ! frtati 2021/10/05

                     do k = 1, np
                        tott(k+1,1) = tott(k+1,1) + tr(29+k,ir,ie,1)
                     end do

                  end do
! sumover
                  itype_het = 2
                  call phetreg_sumover_get(m,iax,
     &             kl,ks,np,itype_het,             ! itype = 1,2,3
     &             idd,ir,1,maxtott,tott)         ! ie = 1 or ir =1 ,ie=0

                  write(iot,'(/"#   sum over",14x,
     &                        1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05

                  write(iot,'(/"#   no. =",i3)') inum

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 6 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------------#"/
     &            "# Stopped energies of each particle (group) #"/
     &            "#-------------------------------------------#"
