     &                     ((tr(29+np+k,ir,iz,0,j),j=1,2),k=1,np) ! frtati 2021/10/05

                        voll = voll + vl(ir,iz)

                        vn = tr(11,ir,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vl(ir,iz)

                        tott(1,1) = tott(1,1) + vn

                     do k = 1, np
                        vn = tr(29+np+k,ir,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vl(ir,iz)
                        tott(k+1,1) = tott(k+1,1) + vn
                     end do

                  end do

                  do k = 1, np + 1
                     if( itunt(m) .eq. 1 ) then
                        tott(k,1) = tott(k,1) / voll
                     end if
                  end do

! sumover
                  itype_het = 3
                  call  phetrz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,ir,1,0,maxtott,tott)        ! ir,iz,ie

                  if( itunt(m) .eq. 1 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  else if( itunt(m) .eq. 2 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/source]")')
                  end if

                  write(iot,'(/"#   no. =",i3,3x,
     &            "ir  =",i3,/
     &            "#   r = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                        inum, ir,
     &                        rm(ir), rm(ir+1), voll

               end if

*-----------------------------------------------------------------------

            end do
            end do

*-----------------------------------------------------------------------
*        r axis
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 6 ) then

               inum = 0

               totht = 0.0

            do iz = 1, nz

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

