     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        zm(iz), zm(iz+1)

               else if( idd .eq. 2 ) then

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
