     &                        "  low neutron, photon"/
     &                        "  low proton"/
     &                        "  and others"/
     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        zm(iz), zm(iz+1)

               else if( idd .eq. 4 ) then

