                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  ionization",
     &                        ",  iy =",i3,
     &                        ",  iz =",i3,a1)')
     &                        cha, inum, iy, iz, cha

                  write(iot,'(
     &            "#----------------------------------------",
     &            "------------------#"/
     &            "# Ionization is the sum of proton, pion+,",
     &            " pion- and others #"/
     &            "#----------------------------------------",
     &            "------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  ionization by"/
     &                        "  proton, pion+-"/
     &                        "  and others"/
     &                        "  ymin  &=&",1pe13.4," [cm]"/
     &                        "  ymax  &=&",1pe13.4," [cm]"/
     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        ym(iy), ym(iy+1), zm(iz), zm(iz+1)

               else if( idd .eq. 6 ) then

                  write(iot,'(/
     &            "#---------------------------------------#"/
     &            "# Stopped particles of proton, neutron, #"/
     &            "#         photon, pion+- and others     #"/
     &            "#---------------------------------------#"/
     &            )')

               else if( idd .eq. 7 ) then

                  write(iot,'(/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            "# Remaining excitation and Fission high",
     &            " energy recoil and low energy Fission #"/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            )')

               end if

*-----------------------------------------------------------------------

            if( idd .le. 5 ) then

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'( "x: x [cm]")')

               else

                  write(iot,'( "x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: Heat ",a17)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &                       ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

            end if

*-----------------------------------------------------------------------

               if( idd .eq. 1 ) then

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "h: n",12x,"x",12x,
     &                       "y(total),hh0l n")')

                 else

                  write(iot,'( "h: n",12x,"x",12x,
     &                       "y1(total),hh0l ny2 dy1=[y1*y2]")')

                 end if

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         "     heat     r.err")')

               else if( idd .eq. 2 ) then

                  write(iot,'( "h: n x ",
     &                       "ny1 n ny2 n ny3 n ny4 n ny5 n ",
     &                       "y6=[y1+y2+y3+y4+y5](leakage),q7rr ",
     &                       "y7=[y6-y4](pcut),m6g ",
     &                       "y8=[y7-y3](gcut),u5b ",
     &                       "y9=[y8-y2](ncut),d4r ",
     &                       "y10=[y1](total),l3")')

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         "    total     r.err  ",
     &                         "     ncut     r.err  ",
     &                         "     gcut     r.err  ",
     &                         "     pcut     r.err  ",
     &                         "  leakage     r.err  ")')

               else if( idd .eq. 3 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, recoil),l3 n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ny6 n ny7 n ",
     &                       "y8=[y1-y2](ionization),d4r ",
     &                       "y9=[y8-y3](low neutron),u5b ",
     &                       "y10=[y9-y4](photon),m6g ",
     &                       "y11=[y10-y5](low proton),q7rr ",
     &                       "y12=[y7](others),v8bb ")')

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         "    total     r.err  ",
     &                         "   recoil     r.err  ",
     &                         "  ionization  r.err  ",
     &                         "  low neutrn  r.err  ",
     &                         "  photon      r.err  ",
     &                         "  low proton  r.err  ",
     &                         "   others     r.err  ")')

               else if( idd .eq. 4 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, deuteron),hh0l n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ny6 n ",
     &                       "y7=[y1-y2](tritium),hh0dr ",
     &                       "y8=[y7-y3](3He),hh0ub ",
     &                       "y9=[y8-y4](alpha),hh0mg ",
     &                       "y10=[y6](residue),hh0qrr")')

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         " total recoil r.err  ",
     &                         "  deuteron    r.err  ",
     &                         "   tritium    r.err  ",
     &                         "     3He      r.err  ",
     &                         "    alpha     r.err  ",
     &                         "  residue     r.err  ")')

               else if( idd .eq. 5 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, others),hh0l n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ",
     &                       "y6=[y1-y5](pion+),hh0dr ",
     &                       "y7=[y6-y3](pion-),hh0ub ",
     &                       "y8=[y2](proton),hh0mg")')

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         "  ionization  r.err  ",
     &                         "    proton    r.err  ",
     &                         "    pion+     r.err  ",
     &                         "    pion-     r.err  ",
     &                         "    others    r.err  ")')

               else if( idd .eq. 6 ) then

                  write(iot,'( "n: n",12x,"x",10x,
     &                         "  ny1(stop proton) n ",
     &                         "  ny2(stp neutron) n ",
     &                         "  ny3(stop photon) n ",
     &                         "  ny4(stop  pion+) n ",
     &                         "  ny5(stop  pion-) n ",
     &                         "  ny6(stop others) n")')

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         "  stop proton r.err  ",
     &                         "  stp neutron r.err  ",
     &                         "  stop photon r.err  ",
     &                         "  stop  pion+ r.err  ",
     &                         "  stop  pion- r.err  ",
     &                         "  stop others r.err  ")')

               else if( idd .eq. 7 ) then

                  write(iot,'( "n: n",12x,"x",10x,
     &                         "  ny1(rem. excit.) n ",
     &                         "  ny2(fision high) n ",
     &                         "  ny3(fission low) n")')

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         "  rem.excit.  r.err  ",
     &                         "  fision high r.err  ",
     &                         "  fission low r.err  ")')

               end if

*-----------------------------------------------------------------------

               do k = 1, ks(idd)
                     tott(k,1) = 0.d+0
               end do

                     voll = 0.0

               do ix = 1, nx

                        write(iot,'(1p2e13.4,7(1pe13.4,0pf8.4))')
     &                  xm(ix),xm(ix+1),
     &                  ((tr(kl(idd,k),ix,iy,iz,0,j),j=1,2),k=1,ks(idd))

                     vlli = vl(ix,iy,iz)
                     voll = voll + vlli

                  do k = 1, ks(idd)
                     vn = tr(kl(idd,k),ix,iy,iz,0,1)
                     if( itunt(m) .eq. 1 ) vn = vn * vlli
                     tott(k,1) = tott(k,1) + vn
                  end do

               end do

               do k = 1, ks(idd)
                  if( itunt(m) .eq. 1 ) then
                     tott(k,1) = tott(k,1) / voll
                  end if
               end do

! sumover
                  itype_het = 1
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,1,iy,iz,0,maxtott,tott)        ! ix,iy,iz,ie

               if( itunt(m) .eq. 1 ) then
                  write(iot,'(/"#   sum over",14x,7(1pe13.4,0pf8.4))')
     &                     (tott(k,1),tott(k,2),k=1,ks(idd))
                  write(iot,'( "#   [MeV/cm^3/source]")')
               else if( itunt(m) .eq. 2 ) then
                  write(iot,'(/"#   sum over",14x,7(1pe13.4,0pf8.4))')
     &                     (tott(k,1),tott(k,2),k=1,ks(idd))
                  write(iot,'( "#   [MeV/source]")')
               end if

               write(iot,'(/"#   no. =",i3,3x,
     &         "iy  =",i3,3x,
     &         "iz  =",i3,/
     &         "#   y = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &         "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &         "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                     inum, iy, iz,
     &                     ym(iy), ym(iy+1),
     &                     zm(iz), zm(iz+1), voll

*-----------------------------------------------------------------------

               if( idd .eq. 1 .or. idd .eq. 2 )  then

                  totht = totht + tott(1,1)

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 5 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------#"/
     &            "# Ionization of each particle (group) #"/
     &            "#-------------------------------------#"
     &            )')

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "n: n",12x,"x",12x,
     &                       "n1(total),l3 n ",6x,
     &                       1000(a10,"),hh0",a3," n "))')
     &                        ( chp(i), chl(i) , i = 1, np_mxang ) ! frtati 2021/10/05 np -> np_mxang

                 else

                  write(iot,'( "n: n",12x,"x",12x,
     &                      "n1(total),l3 n ",6x,
     &         1000(a1,i0,a9,"),hh0",a3
     &         ," ny",i0," dy",i0,"=[y",i0,"*y",i0,"] "))')
     &         ( chp(i)(1:1),i,chp(i)(2:10), chl(i)
     &         ,i+np_mxang,i,i,i+np_mxang, i = 1, np_mxang ) ! frtati 2021/10/05

                 end if

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         "  ionization  r.err ",
     &                    1000(a1,"  ",a8,"    r.err "))')
     &                    ( chb(i), chp(i)(3:10), i = 1, np ) ! frtati 2021/10/05

                  do k = 1, np
                        tott(k+1,1) = 0.d+0
                  end do

                        voll = 0.0

                  do ix = 1, nx

                     write(iot,'(1p2e13.4,1000(1pe13.4,0pf8.4))')
     &                     xm(ix),xm(ix+1),
     &                     (tr(7,ix,iy,iz,0,j),j=1,2),
     &                     ((tr(29+k,ix,iy,iz,0,j),j=1,2),k=1,np) ! frtati 2021/10/05

                        vlli = vl(ix,iy,iz)
                        voll = voll + vlli

                     do k = 1, np
                        vn = tr(29+k,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(k+1,1) = tott(k+1,1) + vn
                     end do

                  end do

                  do k = 1, np
                     if( itunt(m) .eq. 1 ) then
                        tott(k+1,1) = tott(k+1,1) / voll
                     end if

! sumover
                  itype_het = 2
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,1,iy,iz,0,maxtott,tott)        ! ix,iy,iz,ie

                  end do

                  if( itunt(m) .eq. 1 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  else if( itunt(m) .eq. 2 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/source]")')
                  end if

                  write(iot,'(/"#   no. =",i3,3x,
     &            "iy  =",i3,3x,
     &            "iz  =",i3,/
     &            "#   y = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                        inum, iy, iz,
     &                        ym(iy), ym(iy+1),
     &                        zm(iz), zm(iz+1), voll

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 6 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------------#"/
     &            "# Stopped energies of each particle (group) #"/
     &            "#-------------------------------------------#"
     &            )')

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "n: n",12x,"x",12x,
     &                       "n1(total),l3 n ",6x,
     &                       1000(a10,"),hh0",a3," n "))')
     &                        ( chp(i), chl(i) , i = 1, np_mxang ) ! frtati 2021/10/05 np -> np_mxang

                 else

                  write(iot,'( "n: n",12x,"x",12x,
     &                      "n1(total),l3 n ",6x,
     &         1000(a1,i0,a9,"),hh0",a3
     &         ," ny",i0," dy",i0,"=[y",i0,"*y",i0,"] "))')
     &         ( chp(i)(1:1),i,chp(i)(2:10), chl(i)
     &         ,i+np_mxang,i,i,i+np_mxang, i = 1, np_mxang ) ! frtati 2021/10/05

                 end if

                  write(iot,'( "#  x-lower      x-upper    ",
     &                         " total others r.err ",
     &                    1000(a1,"  ",a8,"    r.err "))')
     &                    ( chb(i), chp(i)(3:10), i = 1, np ) ! frtati 2021/10/05

                  do k = 1, np + 1
                        tott(k,1) = 0.d+0
                  end do

                        voll = 0.0

                  do ix = 1, nx

                     write(iot,'(1p2e13.4,1000(1pe13.4,0pf8.4))')
     &                     xm(ix),xm(ix+1),
     &                     (tr(11,ix,iy,iz,0,j),j=1,2),
     &                     ((tr(29+np+k,ix,iy,iz,0,j),j=1,2),k=1,np) ! frtati 2021/10/05

                        vlli = vl(ix,iy,iz)
                        voll = voll + vlli

                        vn = tr(11,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(1,1) = tott(1,1) + vn

                     do k = 1, np
                        vn = tr(29+np+k,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(k+1,1) = tott(k+1,1) + vn
                     end do

                  end do

                  do k = 1, np + 1
                     if( itunt(m) .eq. 1 ) then
                        tott(k,1) = tott(k,1) / voll
                     end if

                  end do

! sumover
                  itype_het = 3
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,1,iy,iz,0,maxtott,tott)        ! ix,iy,iz,ie

                  if( itunt(m) .eq. 1 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  else if( itunt(m) .eq. 2 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/source]")')
                  end if

                  write(iot,'(/"#   no. =",i3,3x,
     &            "iy  =",i3,3x,
     &            "iz  =",i3,/
     &            "#   y = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                        inum, iy, iz,
     &                        ym(iy), ym(iy+1),
     &                        zm(iz), zm(iz+1), voll

               end if

*-----------------------------------------------------------------------

            end do
            end do
            end do

*-----------------------------------------------------------------------
*        y axis
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 4 ) then

               inum = 0

               totht = 0.0

            do ix = 1, nx
            do iz = 1, nz

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn

*-----------------------------------------------------------------------

            if( ns .eq. 3 ) then

               write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

            else if( ns .eq. 2 ) then

               write(iot,'( "p: scal(0.5) xorg(0.1) yorg(0.65)")')

            else if( ns .eq. 1 ) then

               write(iot,'( "p: scal(0.5) xorg(0.1) yorg(1.37)")')

            end if

*-----------------------------------------------------------------------

            do idd = ids, idf

*-----------------------------------------------------------------------

               if( idd .eq. 1 ) then

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  heat",
     &                        ",  ix =",i3,
     &                        ",  iz =",i3,a1)')
     &                        cha, inum, ix, iz, cha

                  write(iot,'(
     &            "#----------------------------------------#"/
     &            "# Total heat without ncut, gcut and pcut #"/
     &            "#----------------------------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  without ncut"/
     &                        "  gcut and pcut"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), zm(iz), zm(iz+1)

               else if( idd .eq. 2 ) then

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  total heat",
     &                        ",  ix =",i3,
     &                        ",  iz =",i3,a1)')
     &                        cha, inum, ix, iz, cha

                  write(iot,'(
     &            "#-------------------------------------",
     &            "---------#"/
     &            "# Total heat with ncut, gcut, pcut and",
     &            " leakage #"/
     &            "#-------------------------------------",
     &            "---------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  add ncut"/
     &                        "  gcut and pcut"/
     &                        "  and leakage"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), zm(iz), zm(iz+1)

               else if( idd .eq. 3 ) then

                  write(iot,'(/"z: xorg(1.8)")')

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  total heat",
     &                        ",  ix =",i3,
     &                        ",  iz =",i3,a1)')
     &                        cha, inum, ix, iz, cha

                  write(iot,'(
     &            "#---------------------------------------------",
     &            "----------------------------------------------#"/
     &            "# Total heat is the sum of recoil, ionization,",
     &            " low neutron,   photon, low proton and others #"/
     &            "#---------------------------------------------",
     &            "----------------------------------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  components of"/
     &                        "  recoil, ionization,"/
     &                        "  low neutron, photon"/
     &                        "  low proton"/
     &                        "  and others"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), zm(iz), zm(iz+1)

               else if( idd .eq. 4 ) then

                  write(iot,'(/"z: xorg(-1.8) yorg(-1.37)")')

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  recoil",
     &                        ",  ix =",i3,
     &                        ",  iz =",i3,a1)')
     &                        cha, inum, ix, iz, cha

                  write(iot,'(
     &            "#------------------------------------------",
     &            "---------#"/
     &            "# Recoil is the sum of d, t, 3He, alpha and",
     &            " residue #"/
     &            "#------------------------------------------",
     &            "---------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  recoil of"/
     &                        "  d, t, 3He, alpha"/
     &                        "  and residue"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), zm(iz), zm(iz+1)

               else if( idd .eq. 5 ) then

                  write(iot,'(/"z: xorg(1.8)")')

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  ionization",
     &                        ",  ix =",i3,
     &                        ",  iz =",i3,a1)')
     &                        cha, inum, ix, iz, cha

                  write(iot,'(
     &            "#----------------------------------------",
     &            "------------------#"/
     &            "# Ionization is the sum of proton, pion+,",
     &            " pion- and others #"/
     &            "#----------------------------------------",
     &            "------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  ionization by"/
     &                        "  proton, pion+-"/
     &                        "  and others"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  zmin  &=&",1pe13.4," [cm]"/
     &                        "  zmax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), zm(iz), zm(iz+1)

               else if( idd .eq. 6 ) then

                  write(iot,'(/
     &            "#---------------------------------------#"/
     &            "# Stopped particles of proton, neutron, #"/
     &            "#         photon, pion+- and others     #"/
     &            "#---------------------------------------#"/
     &            )')

               else if( idd .eq. 7 ) then

                  write(iot,'(/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            "# Remaining excitation and Fission high",
     &            " energy recoil and low energy Fission #"/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            )')

               end if

*-----------------------------------------------------------------------

            if( idd .le. 5 ) then

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'( "x: y [cm]")')

               else

                  write(iot,'( "x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: Heat ",a17)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &            ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

            end if

*-----------------------------------------------------------------------

               if( idd .eq. 1 ) then

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "h: n",12x,"x",12x,
     &                       "y(total),hh0l n")')

                 else

                  write(iot,'( "h: n",12x,"x",12x,
     &                       "y1(total),hh0l ny2 dy1=[y1*y2]")')

                 end if

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         "     heat     r.err")')

               else if( idd .eq. 2 ) then

                  write(iot,'( "h: n x ",
     &                       "ny1 n ny2 n ny3 n ny4 n ny5 n ",
     &                       "y6=[y1+y2+y3+y4+y5](leakage),q7rr ",
     &                       "y7=[y6-y4](pcut),m6g ",
     &                       "y8=[y7-y3](gcut),u5b ",
     &                       "y9=[y8-y2](ncut),d4r ",
     &                       "y10=[y1](total),l3")')

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         "    total     r.err  ",
     &                         "     ncut     r.err  ",
     &                         "     gcut     r.err  ",
     &                         "     pcut     r.err  ",
     &                         "  leakage     r.err  ")')

               else if( idd .eq. 3 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, recoil),l3 n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ny6 n ny7 n ",
     &                       "y8=[y1-y2](ionization),d4r ",
     &                       "y9=[y8-y3](low neutron),u5b ",
     &                       "y10=[y9-y4](photon),m6g ",
     &                       "y11=[y10-y5](low proton),q7rr ",
     &                       "y12=[y7](others),v8bb ")')

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         "    total     r.err  ",
     &                         "   recoil     r.err  ",
     &                         "  ionization  r.err  ",
     &                         "  low neutrn  r.err  ",
     &                         "  photon      r.err  ",
     &                         "  low proton  r.err  ",
     &                         "   others     r.err  ")')

               else if( idd .eq. 4 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, deuteron),hh0l n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ny6 n ",
     &                       "y7=[y1-y2](tritium),hh0dr ",
     &                       "y8=[y7-y3](3He),hh0ub ",
     &                       "y9=[y8-y4](alpha),hh0mg ",
     &                       "y10=[y6](residue),hh0qrr")')

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         " total recoil r.err  ",
     &                         "  deuteron    r.err  ",
     &                         "   tritium    r.err  ",
     &                         "     3He      r.err  ",
     &                         "    alpha     r.err  ",
     &                         "  residue     r.err  ")')

               else if( idd .eq. 5 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, others),hh0l n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ",
     &                       "y6=[y1-y5](pion+),hh0dr ",
     &                       "y7=[y6-y3](pion-),hh0ub ",
     &                       "y8=[y2](proton),hh0mg")')

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         "  ionization  r.err  ",
     &                         "    proton    r.err  ",
     &                         "    pion+     r.err  ",
     &                         "    pion-     r.err  ",
     &                         "    others    r.err  ")')

               else if( idd .eq. 6 ) then

                  write(iot,'( "n: n",12x,"x",10x,
     &                         "  ny1(stop proton) n ",
     &                         "  ny2(stp neutron) n ",
     &                         "  ny3(stop photon) n ",
     &                         "  ny4(stop  pion+) n ",
     &                         "  ny5(stop  pion-) n ",
     &                         "  ny6(stop others) n")')

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         "  stop proton r.err  ",
     &                         "  stp neutron r.err  ",
     &                         "  stop photon r.err  ",
     &                         "  stop  pion+ r.err  ",
     &                         "  stop  pion- r.err  ",
     &                         "  stop others r.err  ")')

               else if( idd .eq. 7 ) then

                  write(iot,'( "n: n",12x,"x",10x,
     &                         "  ny1(rem. excit.) n ",
     &                         "  ny2(fision high) n ",
     &                         "  ny3(fission low) n")')

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         "  rem.excit.  r.err  ",
     &                         "  fision high r.err  ",
     &                         "  fission low r.err  ")')

               end if

*-----------------------------------------------------------------------

               do k = 1, ks(idd)
                     tott(k,1) = 0.d+0
               end do

                     voll = 0.0

               do iy = 1, ny

                  write(iot,'(1p2e13.4,7(1pe13.4,0pf8.4))')
     &                  ym(iy),ym(iy+1),
     &                  ((tr(kl(idd,k),ix,iy,iz,0,j),j=1,2),k=1,ks(idd))

                     vlli = vl(ix,iy,iz)
                     voll = voll + vlli

                  do k = 1, ks(idd)
                     vn = tr(kl(idd,k),ix,iy,iz,0,1)
                     if( itunt(m) .eq. 1 ) vn = vn * vlli
                     tott(k,1) = tott(k,1) + vn
                  end do

               end do

               do k = 1, ks(idd)
                  if( itunt(m) .eq. 1 ) then
                     tott(k,1) = tott(k,1) / voll
                  end if
               end do

! sumover
                  itype_het = 1
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,ix,1,iz,0,maxtott,tott)        ! ix,iy,iz,ie

               if( itunt(m) .eq. 1 ) then
                 write(iot,'(/"#   sum over",14x,7(1pe13.4,0pf8.4))')
     &                     (tott(k,1),tott(k,2),k=1,ks(idd))
                 write(iot,'( "#   [MeV/cm^3/source]")')
               else if( itunt(m) .eq. 2 ) then
                 write(iot,'(/"#   sum over",14x,7(1pe13.4,0pf8.4))')
     &                     (tott(k,1),tott(k,2),k=1,ks(idd))
                 write(iot,'( "#   [MeV/source]")')
               end if

               write(iot,'(/"#   no. =",i3,3x,
     &         "ix  =",i3,3x,
     &         "iz  =",i3,/
     &         "#   x = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &         "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &         "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                     inum, ix, iz,
     &                     xm(ix), xm(ix+1),
     &                     zm(iz), zm(iz+1), voll

*-----------------------------------------------------------------------

               if( idd .eq. 1 .or. idd .eq. 2 )  then

                  totht = totht + tott(1,1)

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 5 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------#"/
     &            "# Ionization of each particle (group) #"/
     &            "#-------------------------------------#"
     &            )')

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "n: n",12x,"x",12x,
     &                       "n1(total),l3 n ",6x,
     &                       1000(a10,"),hh0",a3," n "))')
     &                        ( chp(i), chl(i) , i = 1, np_mxang ) ! frtati 2021/10/05 np -> np_mxang

                 else

                  write(iot,'( "n: n",12x,"x",12x,
     &                      "n1(total),l3 n ",6x,
     &         1000(a1,i0,a9,"),hh0",a3
     &         ," ny",i0," dy",i0,"=[y",i0,"*y",i0,"] "))')
     &         ( chp(i)(1:1),i,chp(i)(2:10), chl(i)
     &         ,i+np_mxang,i,i,i+np_mxang, i = 1, np_mxang ) ! frtati 2021/10/05

                 end if

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         "  ionization  r.err ",
     &                    1000(a1,"  ",a8,"    r.err "))')
     &                    ( chb(i), chp(i)(3:10), i = 1, np ) ! frtati 2021/10/05

                  do k = 1, np
                        tott(k+1,1) = 0.d+0
                  end do

                        voll = 0.0

                  do iy = 1, ny

                     write(iot,'(1p2e13.4,1000(1pe13.4,0pf8.4))')
     &                     ym(iy),ym(iy+1),
     &                     (tr(7,ix,iy,iz,0,j),j=1,2),
     &                     ((tr(29+k,ix,iy,iz,0,j),j=1,2),k=1,np) ! frtati 2021/10/05

                        vlli = vl(ix,iy,iz)
                        voll = voll + vlli

                     do k = 1, np
                        vn = tr(29+k,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(k+1,1) = tott(k+1,1) + vn
                     end do

                  end do

                  do k = 1, np
                     if( itunt(m) .eq. 1 )  then
                        tott(k+1,1) = tott(k+1,1) / voll
                     end if
                  end do

! sumover
                  itype_het = 2
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,ix,1,iz,0,maxtott,tott)        ! ix,iy,iz,ie

                  if( itunt(m) .eq. 1 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  else if( itunt(m) .eq. 2 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/source]")')
                  end if

                  write(iot,'(/"#   no. =",i3,3x,
     &            "ix  =",i3,3x,
     &            "iz  =",i3,/
     &            "#   x = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                        inum, ix, iz,
     &                        xm(ix), xm(ix+1),
     &                        zm(iz), zm(iz+1), voll

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 6 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------------#"/
     &            "# Stopped energies of each particle (group) #"/
     &            "#-------------------------------------------#"
     &            )')

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "n: n",12x,"x",12x,
     &                       "n1(total),l3 n ",6x,
     &                       1000(a10,"),hh0",a3," n "))')
     &                        ( chp(i), chl(i) , i = 1, np_mxang ) ! frtati 2021/10/05 np -> np_mxang

                 else

                  write(iot,'( "n: n",12x,"x",12x,
     &                      "n1(total),l3 n ",6x,
     &         1000(a1,i0,a9,"),hh0",a3
     &         ," ny",i0," dy",i0,"=[y",i0,"*y",i0,"] "))')
     &         ( chp(i)(1:1),i,chp(i)(2:10), chl(i)
     &         ,i+np_mxang,i,i,i+np_mxang, i = 1, np_mxang ) ! frtati 2021/10/05

                 end if

                  write(iot,'( "#  y-lower      y-upper    ",
     &                         " total others r.err ",
     &                    1000(a1,"  ",a8,"    r.err "))')
     &                    ( chb(i), chp(i)(3:10), i = 1, np ) ! frtati 2021/10/05

                  do k = 1, np + 1
                        tott(k,1) = 0.d+0
                  end do

                        voll = 0.0

                  do iy = 1, ny

                     write(iot,'(1p2e13.4,1000(1pe13.4,0pf8.4))')
     &                     ym(iy),ym(iy+1),
     &                     (tr(11,ix,iy,iz,0,j),j=1,2),
     &                     ((tr(29+np+k,ix,iy,iz,0,j),j=1,2),k=1,np) ! frtati 2021/10/05

                        vlli = vl(ix,iy,iz)
                        voll = voll + vlli

                        vn = tr(11,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(1,1) = tott(1,1) + vn

                     do k = 1, np
                        vn = tr(29+np+k,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(k+1,1) = tott(k+1,1) + vn
                     end do

                  end do

                  do k = 1, np + 1
                     if( itunt(m) .eq. 1 ) then
                        tott(k,1) = tott(k,1) / voll
                     end if
                  end do

! sumover
                  itype_het = 3
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,ix,1,iz,0,maxtott,tott)        ! ix,iy,iz,ie

                  if( itunt(m) .eq. 1 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  else if( itunt(m) .eq. 2 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  end if

                  write(iot,'(/"#   no. =",i3,3x,
     &            "ix  =",i3,3x,
     &            "iz  =",i3,/
     &            "#   x = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                        inum, ix, iz,
     &                        xm(ix), xm(ix+1),
     &                        zm(iz), zm(iz+1), voll

               end if

*-----------------------------------------------------------------------

            end do
            end do
            end do

*-----------------------------------------------------------------------
*        z axis
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 5 ) then

               inum = 0

               totht = 0.0

            do ix = 1, nx
            do iy = 1, ny

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn

*-----------------------------------------------------------------------

            if( ns .eq. 3 ) then

               write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

            else if( ns .eq. 2 ) then

               write(iot,'( "p: scal(0.5) xorg(0.1) yorg(0.65)")')

            else if( ns .eq. 1 ) then

               write(iot,'( "p: scal(0.5) xorg(0.1) yorg(1.37)")')

            end if

*-----------------------------------------------------------------------

            do idd = ids, idf

*-----------------------------------------------------------------------

               if( idd .eq. 1 ) then

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  heat",
     &                        ",  ix =",i3,
     &                        ",  iy =",i3,a1)')
     &                        cha, inum, ix, iy, cha

                  write(iot,'(
     &            "#----------------------------------------#"/
     &            "# Total heat without ncut, gcut and pcut #"/
     &            "#----------------------------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  without ncut"/
     &                        "  gcut and pcut"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  ymin  &=&",1pe13.4," [cm]"/
     &                        "  ymax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), ym(iy), ym(iy+1)

               else if( idd .eq. 2 ) then

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  total heat",
     &                        ",  ix =",i3,
     &                        ",  iy =",i3,a1)')
     &                        cha, inum, ix, iy, cha

                  write(iot,'(
     &            "#-------------------------------------",
     &            "---------#"/
     &            "# Total heat with ncut, gcut, pcut and",
     &            " leakage #"/
     &            "#-------------------------------------",
     &            "---------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  add ncut"/
     &                        "  gcut and pcut"/
     &                        "  and leakage"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  ymin  &=&",1pe13.4," [cm]"/
     &                        "  ymax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), ym(iy), ym(iy+1)

               else if( idd .eq. 3 ) then

                  write(iot,'(/"z: xorg(1.8)")')

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  total heat",
     &                        ",  ix =",i3,
     &                        ",  iy =",i3,a1)')
     &                        cha, inum, ix, iy, cha

                  write(iot,'(
     &            "#---------------------------------------------",
     &            "----------------------------------------------#"/
     &            "# Total heat is the sum of recoil, ionization,",
     &            " low neutron,   photon, low proton and others #"/
     &            "#---------------------------------------------",
     &            "----------------------------------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  components of"/
     &                        "  recoil, ionization,"/
     &                        "  low neutron, photon"/
     &                        "  low proton"/
     &                        "  and others"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  ymin  &=&",1pe13.4," [cm]"/
     &                        "  ymax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), ym(iy), ym(iy+1)

               else if( idd .eq. 4 ) then

                  write(iot,'(/"z: xorg(-1.8) yorg(-1.37)")')

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  recoil",
     &                        ",  ix =",i3,
     &                        ",  iy =",i3,a1)')
     &                        cha, inum, ix, iy, cha

                  write(iot,'(
     &            "#------------------------------------------",
     &            "---------#"/
     &            "# Recoil is the sum of d, t, 3He, alpha and",
     &            " residue #"/
     &            "#------------------------------------------",
     &            "---------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  recoil of"/
     &                        "  d, t, 3He, alpha"/
     &                        "  and residue"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  ymin  &=&",1pe13.4," [cm]"/
     &                        "  ymax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), ym(iy), ym(iy+1)

               else if( idd .eq. 5 ) then

                  write(iot,'(/"z: xorg(1.8)")')

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

                  write(iot,'(/a1,"no. =",i3,
     &                        ",  ionization",
     &                        ",  ix =",i3,
     &                        ",  iy =",i3,a1)')
     &                        cha, inum, ix, iy, cha

                  write(iot,'(
     &            "#----------------------------------------",
     &            "------------------#"/
     &            "# Ionization is the sum of proton, pion+,",
     &            " pion- and others #"/
     &            "#----------------------------------------",
     &            "------------------#"
     &            )')

                  write(iot,'("wt: s(0.7)",/
     &                        a1,"vspace{-3}"/
     &                        "  ionization by"/
     &                        "  proton, pion+-"/
     &                        "  and others"/
     &                        "  xmin  &=&",1pe13.4," [cm]"/
     &                        "  xmax  &=&",1pe13.4," [cm]"/
     &                        "  ymin  &=&",1pe13.4," [cm]"/
     &                        "  ymax  &=&",1pe13.4," [cm]"/
     &                        "e:")')
     &                        yen,
     &                        xm(ix), xm(ix+1), ym(iy), ym(iy+1)

               else if( idd .eq. 6 ) then

                  write(iot,'(/
     &            "#---------------------------------------#"/
     &            "# Stopped particles of proton, neutron, #"/
     &            "#         photon, pion+- and others     #"/
     &            "#---------------------------------------#"/
     &            )')

               else if( idd .eq. 7 ) then

                  write(iot,'(/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            "# Remaining excitation and Fission high",
     &            " energy recoil and low energy Fission #"/
     &            "#--------------------------------------",
     &            "--------------------------------------#"/
     &            )')

               end if

*-----------------------------------------------------------------------

            if( idd .le. 5 ) then

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'( "x: z [cm]")')

               else

                  write(iot,'( "x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: Heat ",a17)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &                       ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

            end if

*-----------------------------------------------------------------------

               if( idd .eq. 1 ) then

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "h: n",12x,"x",12x,
     &                       "y(total),hh0l n")')

                 else

                  write(iot,'( "h: n",12x,"x",12x,
     &                       "y1(total),hh0l ny2 dy1=[y1*y2]")')

                 end if

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         "     heat     r.err")')

               else if( idd .eq. 2 ) then

                  write(iot,'( "h: n x ",
     &                       "ny1 n ny2 n ny3 n ny4 n ny5 n ",
     &                       "y6=[y1+y2+y3+y4+y5](leakage),q7rr ",
     &                       "y7=[y6-y4](pcut),m6g ",
     &                       "y8=[y7-y3](gcut),u5b ",
     &                       "y9=[y8-y2](ncut),d4r ",
     &                       "y10=[y1](total),l3")')

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         "    total     r.err  ",
     &                         "     ncut     r.err  ",
     &                         "     gcut     r.err  ",
     &                         "     pcut     r.err  ",
     &                         "  leakage     r.err  ")')

               else if( idd .eq. 3 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, recoil),l3 n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ny6 n ny7 n ",
     &                       "y8=[y1-y2](ionization),d4r ",
     &                       "y9=[y8-y3](low neutron),u5b ",
     &                       "y10=[y9-y4](photon),m6g ",
     &                       "y11=[y10-y5](low proton),q7rr ",
     &                       "y12=[y7](others),v8bb ")')

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         "    total     r.err  ",
     &                         "   recoil     r.err  ",
     &                         "  ionization  r.err  ",
     &                         "  low neutrn  r.err  ",
     &                         "  photon      r.err  ",
     &                         "  low proton  r.err  ",
     &                         "   others     r.err  ")')

               else if( idd .eq. 4 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, deuteron),hh0l n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ny6 n ",
     &                       "y7=[y1-y2](tritium),hh0dr ",
     &                       "y8=[y7-y3](3He),hh0ub ",
     &                       "y9=[y8-y4](alpha),hh0mg ",
     &                       "y10=[y6](residue),hh0qrr")')

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         " total recoil r.err  ",
     &                         "  deuteron    r.err  ",
     &                         "   tritium    r.err  ",
     &                         "     3He      r.err  ",
     &                         "    alpha     r.err  ",
     &                         "  residue     r.err  ")')

               else if( idd .eq. 5 ) then

                  write(iot,'( "h: n x ",
     &                       "y1(total, others),hh0l n ",
     &                       "ny2 n ny3 n ny4 n ny5 n ",
     &                       "y6=[y1-y5](pion+),hh0dr ",
     &                       "y7=[y6-y3](pion-),hh0ub ",
     &                       "y8=[y2](proton),hh0mg")')

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         "  ionization  r.err  ",
     &                         "    proton    r.err  ",
     &                         "    pion+     r.err  ",
     &                         "    pion-     r.err  ",
     &                         "    others    r.err  ")')

               else if( idd .eq. 6 ) then

                  write(iot,'( "n: n",12x,"x",10x,
     &                         "  ny1(stop proton) n ",
     &                         "  ny2(stp neutron) n ",
     &                         "  ny3(stop photon) n ",
     &                         "  ny4(stop  pion+) n ",
     &                         "  ny5(stop  pion-) n ",
     &                         "  ny6(stop others) n")')

                  write(iot,'( "#  z-lower      z-upper    ",
