     &                         "  stop photon r.err  ",
     &                         "  stop  pion+ r.err  ",
     &                         "  stop  pion- r.err  ",
     &                         "  stop others r.err  ")')

               else if( idd .eq. 7 ) then

                  write(iot,'( "n: n",12x,"x",10x,
     &                         "  ny1(rem. excit.) n ",
     &                         "  ny2(fision high) n ",
     &                         "  ny3(fission low) n")')

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         "  rem.excit.  r.err  ",
     &                         "  fision high r.err  ",
     &                         "  fission low r.err  ")')

               end if

*-----------------------------------------------------------------------

               do k = 1, ks(idd)
                     tott(k,1) = 0.d+0
               end do

                     voll = 0.0

               do iz = 1, nz

                  write(iot,'(1p2e13.4,7(1pe13.4,0pf8.4))')
     &                  zm(iz),zm(iz+1),
     &                  ((tr(kl(idd,k),ix,iy,iz,0,j),j=1,2),k=1,ks(idd))

                     vlli = vl(ix,iy,iz)
                     voll = voll + vlli

                  do k = 1, ks(idd)
                     vn = tr(kl(idd,k),ix,iy,iz,0,1)
                     if( itunt(m) .eq. 1 ) vn = vn * vlli
                     tott(k,1) = tott(k,1) + vn
                  end do

               end do

               do k = 1, ks(idd)
                  if( itunt(m) .eq. 1 ) then
                     tott(k,1) = tott(k,1) / voll
                  end if
               end do

! sumover
                  itype_het = 1
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,ix,iy,1,0,maxtott,tott)        ! ix,iy,iz,ie

               if( itunt(m) .eq. 1 ) then
                 write(iot,'(/"#   sum over",14x,7(1pe13.4,0pf8.4))')
     &                     (tott(k,1),tott(k,2),k=1,ks(idd))
                 write(iot,'( "#   [MeV/cm^3/source]")')
               else if( itunt(m) .eq. 2 ) then
                 write(iot,'(/"#   sum over",14x,7(1pe13.4,0pf8.4))')
     &                     (tott(k,1),tott(k,2),k=1,ks(idd))
                 write(iot,'( "#   [MeV/source]")')
               end if

               write(iot,'(/"#   no. =",i3,3x,
     &         "ix  =",i3,3x,
     &         "iy  =",i3,/
     &         "#   x = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &         "#   y = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &         "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                     inum, ix, iy,
     &                     xm(ix), xm(ix+1),
     &                     ym(iy), ym(iy+1), voll

*-----------------------------------------------------------------------

               if( idd .eq. 1 .or. idd .eq. 2 )  then

                  totht = totht + tott(1,1)

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 5 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------#"/
     &            "# Ionization of each particle (group) #"/
     &            "#-------------------------------------#"
     &            )')

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "n: n",12x,"x",12x,
     &                       "n1(total),l3 n ",6x,
     &                       1000(a10,"),hh0",a3," n "))')
     &                        ( chp(i), chl(i) , i = 1, np_mxang ) ! frtati 2021/10/05 np -> np_mxang

                 else

                  write(iot,'( "n: n",12x,"x",12x,
     &                      "n1(total),l3 n ",6x,
     &         1000(a1,i0,a9,"),hh0",a3
     &         ," ny",i0," dy",i0,"=[y",i0,"*y",i0,"] "))')
     &         ( chp(i)(1:1),i,chp(i)(2:10), chl(i)
     &         ,i+np_mxang,i,i,i+np_mxang, i = 1, np_mxang ) ! frtati 2021/10/05

                 end if

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         "  ionization  r.err ",
     &                    1000(a1,"  ",a8,"    r.err "))')
     &                    ( chb(i), chp(i)(3:10), i = 1, np ) ! frtati 2021/10/05

                  do k = 1, np
                        tott(k+1,1) = 0.d+0
                  end do

                        voll = 0.0

                  do iz = 1, nz

                     write(iot,'(1p2e13.4,1000(1pe13.4,0pf8.4))')
     &                     zm(iz),zm(iz+1),
     &                     (tr(7,ix,iy,iz,0,j),j=1,2),
     &                     ((tr(29+k,ix,iy,iz,0,j),j=1,2),k=1,np) ! frtati 2021/10/05

                        vlli = vl(ix,iy,iz)
                        voll = voll + vlli

                     do k = 1, np
                        vn = tr(29+k,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(k+1,1) = tott(k+1,1) + vn
                     end do

                  end do

                  do k = 1, np
                     if( itunt(m) .eq. 1 ) then
                        tott(k+1,1) = tott(k+1,1) / voll
                     end if
                  end do

! sumover
                  itype_het = 2
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,ix,iy,1,0,maxtott,tott)        ! ix,iy,iz,ie

                  if( itunt(m) .eq. 1 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  else if( itunt(m) .eq. 2 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/source]")')
                  end if

                  write(iot,'(/"#   no. =",i3,3x,
     &            "ix  =",i3,3x,
     &            "iy  =",i3,/
     &            "#   x = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   y = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                        inum, ix, iy,
     &                        xm(ix), xm(ix+1),
     &                        ym(iy), ym(iy+1), voll

               end if

*-----------------------------------------------------------------------

               if( idd .eq. 6 .and. np .gt. 0 ) then

                  write(iot,'(/
     &            "#-------------------------------------------#"/
     &            "# Stopped energies of each particle (group) #"/
     &            "#-------------------------------------------#"
     &            )')

c S.H. added IF statement below for epsout=2 (2017.2.18)
                 if ( iteps(m) .ne. 2 ) then

                  write(iot,'( "n: n",12x,"x",12x,
     &                       "n1(total),l3 n ",6x,
     &                       1000(a10,"),hh0",a3," n "))')
     &                        ( chp(i), chl(i) , i = 1, np_mxang ) ! frtati 2021/10/05 np -> np_mxang

                 else

                  write(iot,'( "n: n",12x,"x",12x,
     &                      "n1(total),l3 n ",6x,
     &         1000(a1,i0,a9,"),hh0",a3
     &         ," ny",i0," dy",i0,"=[y",i0,"*y",i0,"] "))')
     &         ( chp(i)(1:1),i,chp(i)(2:10), chl(i)
     &         ,i+np_mxang,i,i,i+np_mxang, i = 1, np_mxang ) ! frtati 2021/10/05

                 end if

                  write(iot,'( "#  z-lower      z-upper    ",
     &                         " total others r.err ",
     &                    1000(a1,"  ",a8,"    r.err "))')
     &                    ( chb(i), chp(i)(3:10), i = 1, np ) ! frtati 2021/10/05

                  do k = 1, np + 1
                        tott(k,1) = 0.d+0
                  end do

                        voll = 0.0

                  do iz = 1, nz

                     write(iot,'(1p2e13.4,1000(1pe13.4,0pf8.4))')
     &                     zm(iz),zm(iz+1),
     &                     (tr(11,ix,iy,iz,0,j),j=1,2),
     &                     ((tr(29+np+k,ix,iy,iz,0,j),j=1,2),k=1,np) ! frtati 2021/10/05

                        vlli = vl(ix,iy,iz)
                        voll = voll + vlli

                        vn = tr(11,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(1,1) = tott(1,1) + vn

                     do k = 1, np
                        vn = tr(29+np+k,ix,iy,iz,0,1)
                        if( itunt(m) .eq. 1 ) vn = vn * vlli
                        tott(k+1,1) = tott(k+1,1) + vn
                     end do

                  end do

                  do k = 1, np + 1
                     if( itunt(m) .eq. 1 ) then
                        tott(k,1) = tott(k,1) / voll
                     end if
                  end do

! sumover
                  itype_het = 3
                  call  phetxyz_sumover_get(m,iax,
     &                   kl,ks,np,itype_het,             ! itype_het = 1,2,3
     &                  idd,ix,iy,1,0,maxtott,tott)        ! ix,iy,iz,ie

                  if( itunt(m) .eq. 1 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/cm^3/source]")')
                  else if( itunt(m) .eq. 2 ) then
                    write(iot,'(/"#   sum over",14x,
     &                    1000(1pe13.4,0pf8.4))')
     &                        tott(1,1),tott(1,2),
     &                        (tott(k,1),tott(k,2),k=2,np+1) ! frtati 2021/10/05
                    write(iot,'( "#   [MeV/source]")')
                  end if

                  write(iot,'(/"#   no. =",i3,3x,
     &            "ix  =",i3,3x,
     &            "iy  =",i3,/
     &            "#   x = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   y = (",1p1e13.4,"  -",1p1e13.4,"  )"/
     &            "#   vol sum =  ",1p1e13.4," [cm^3]")')
     &                        inum, ix, iy,
     &                        xm(ix), xm(ix+1),
     &                        ym(iy), ym(iy+1), voll

               end if

*-----------------------------------------------------------------------

            end do
            end do
            end do

*-----------------------------------------------------------------------
*        xy axis (matrix)
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 7 ) then

               if( ittwo(m) .eq. 1 ) then

                  dc2 = 'h2: '

               else if( ittwo(m) .eq. 2 ) then

                  dc2 = 'hd: '

               else if( ittwo(m) .eq. 3 ) then

                  dc2 = 'hc: '

               else if( ittwo(m) .eq. 6 ) then

                  dc2 = 'hd2:'

               else if( ittwo(m) .eq. 7 ) then

                  dc2 = 'hc2:'

               end if

*-----------------------------------------------------------------------

               inum = 0

            do iz = 1, nz
            do ip = 1, idw

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               write(iot,'("#   no. =",i3,3x,
     &         "iz  =",i3/
     &         "#   z = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     inum, iz,
     &                     zm(iz), zm(iz+1)

*-----------------------------------------------------------------------

            if( ittwo(m) .le. 3 .or. ittwo(m) .ge. 6 ) then

               write(iot,'(/a1,"no. =",i3,
     &                     ",  iz =",i3,
     &                     ",  ",a10,a1)')
     &                     cha, inum, iz, cht(ip), cha

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: x [cm]")')

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: y [cm]")')

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

*-----------------------------------------------------------------------

               if( inum .eq. 1 ) then

                  form  = ( ym(ny+1) - ym(1) )
     &                  / ( xm(nx+1) - xm(1) )
                  xfac  = 0.9
                  afac  = 0.8
                  izlog = 1
                  inocm = 1
                  inolg = 1

                  if( itanl(m) .gt. 0 )
     &            call anset(itang(m),itanl(m),
     &                       form,xfac,afac,cmin,cmax,izlog,inocm,inolg)

                  if( form .le. 1.0 ) then

                     scal = form**0.35
                     xfac = xfac / form**0.5
                     xorg = 0.0
                     yorg = min( 20.d0, ( 1.0 / form - 1.0 ) / 2.5 )

                  else

                     scal = 1.0 / form**0.41
                     xfac = xfac / form**0.5
                     xorg = min( 20.d0, ( form - 1.0 ) / 1.5)
                     yorg = 0.0

                  end if

               end if

                  write(iot,'( "set: c1[",f6.3,
     &                            "] c2[",f6.3,
     &                            "] c5[",f6.3,
     &                            "] c6[",f6.3,
     &                            "] c7[",f6.3,
     &                            "] c8[",f6.3,"]")')
     &                    form, xfac, afac, scal, xorg, yorg
                  write(iot,'( "p: h2fs form[c1] xfac[c2]",
     &                 " afac[c5] scal[c6] xorg[c7] yorg[c8] nosp")')

               if( ( ( ittwo(m) .ge. 2 .and. ittwo(m) .le. 3 ) .or.
     &               ( ittwo(m) .ge. 6 .and. ittwo(m) .le. 7 ) ) .and.
     &             cmin .gt. 0.0 .and. cmax .gt. cmin ) then

                if (ioe .eq. 1 ) then
                  write(iot,'( "set: c3[",1p1e15.6,"] c4[",
     &                  1p1e15.6,"]")') cmin, cmax
                else
                  write(iot,'( "set: c3[1.0e-4] c4[1.0]")')
                end if
                  write(iot,'( "p: cmin[c3] cmax[c4]")')
