               call open_file(iunit_vtk_g_default,
     &                 outFilename, iunit_vtk_g, ios, isText)
               call vtk_write_polydata(
     &                 itvtkfmt(m), iunit_vtk_g,
     &                 isunit_vtk_geom, isunit_vtk_geom_meta)
               call close_file(iunit_vtk_g)

            end if

         end if

         if ( allocated(bmpfIType) ) deallocate( bmpfIType )
         if ( allocated(bmpfIndex) ) deallocate( bmpfIndex )

         call close_file(isunit_vtk_rm)
         call close_file(isunit_vtk_geom)
         call close_file(isunit_vtk_geom_meta)

*-----------------------------------------------------------------------

  900    continue

*-----------------------------------------------------------------------
         deallocate( ixyz )
! sumover
         deallocate(vl_x,vl_y,vl_z)


      return
      end

************************************************************************
*                                                                      *
      subroutine ttracreg(ncol,m,nl,lt,np,nr,mr,ne,nm,nt,mftal,
     &                    kr,eb,tb,tr,trEVENT)
*                                                                      *
*       track length tally in region mesh                              *
*       last modified by D.OBINATA on 2012/04/24                       *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              0 : end of batch                                        *
*              4 : source particle                                     *
*                                                                      *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
!$    use omp_lib
      use talmod, only: prodenmnmx, iprodenhead ! S.H. 2024.4.3
*-----------------------------------------------------------------------
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

      parameter( rlit = 29.97925d0 )

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)

*-----------------------------------------------------------------------
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100
      common /cntreg/ ncntc(3), ncreg(3), incrc(3), incrt(3), kcont(3)
      dimension idas(mdas*2) !2024.6.25 S.H. temporary for fbounds-check
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)
      common /regdc/  idrg(kvlmax), idgr(kvmmax)

      common /tall82/ itcnth(9,itlmax)

      common /tall93/ tprodenmn(itlmax), tprodenmx(itlmax),
     &     nbtproden(itlmax), itprodenchk(itlmax) !S.H. extstat 2024.4.28
      integer noverproden
      data noverproden/0/
      save noverproden
!$OMP THREADPRIVATE(noverproden)
      integer noverprodenlim
      data noverprodenlim/4/

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   tb(nt+1)
c$$$      dimension   tr(np,ne,nt,nr,nm,2)
      dimension   tr(np,ne,nt,nr,nm,mftal) ! S.H. extstat 2024.3.13
      dimension   trEVENT(np,ne,nt,nr,nm)       !OBINATA(2012.5.29): as Ct
      real(8),allocatable,save:: tr0(:,:,:,:,:) !OBINATA(2012.5.29): as C

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension facm(6)

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /egs5cmn10/denstepold,denstepnew,deinit
      real*8            denstepold,denstepnew,deinit
!$OMP THREADPRIVATE(/egs5cmn10/)


      common /  tscmsg   / ktsc(kvlmax), mntsc, ntsc(kvlmax)
      common /  tscreg   / ntscell(kvlmax)
      common / etsminmax / etsmin, etsmax

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------

      nproden = nbtproden(m) !  bin number for probability density function

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.5.29): change tr(,,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,:,:,1) = tr(:,:,:,:,:,1) + trEVENT(:,:,:,:,:)
             tr(:,:,:,:,:,2) = tr(:,:,:,:,:,2) + trEVENT(:,:,:,:,:) ** 2

! sumover
             call ttracreg_sumover(m,1,
     &                   np,    ne,    nt,    nr,    nm,    trEVENT)

c S.H. extstat 2024.3.18
            if ( mftal .ge. 5 ) then
             tr(:,:,:,:,:,3) = tr(:,:,:,:,:,3) + trEVENT(:,:,:,:,:) ** 3
             tr(:,:,:,:,:,4) = tr(:,:,:,:,:,4) + trEVENT(:,:,:,:,:) ** 4
            end if
c S.H. extstat 2024.3.18

c S.H. extstat 2024.3.18
            if ( mftal .gt. 5 ) then

             iprodenmnmx = iprodenhead(m) - 1
             do im = 1, nm
             do ir = 1, nr
             do it = 1, nt
             do ie = 1, ne
             do ip = 1, np
               iprodenmnmx = iprodenmnmx + 1

              score = trEVENT(ip,ie,it,ir,im)
              if ( score .gt. 0d0 ) then

               if ( itprodenchk(m) .eq. 0 ) then
                if ( score .lt. tr(ip,ie,it,ir,im,6) ) then
                   tr(ip,ie,it,ir,im,6) = score/10d0
                   prodenmnmx(1,iprodenmnmx) = score/10d0
                 do iproden = 1, nproden
                    tr(ip,ie,it,ir,im,iproden+8) = 0d0
                 end do
                end if
                if ( score .gt. tr(ip,ie,it,ir,im,7) ) then
                   tr(ip,ie,it,ir,im,7) = score*10d0
                   prodenmnmx(2,iprodenmnmx) = score*10d0
                 do iproden = 1, nproden
                    tr(ip,ie,it,ir,im,iproden+8) = 0d0
                 end do
                end if
               end if

               prodenmn = prodenmnmx(1,iprodenmnmx)
               prodenmx = prodenmnmx(2,iprodenmnmx)

               dproden = dlog(prodenmx/prodenmn) / dble(nproden)
               iproden = idnint(dlog(score/prodenmn)/dproden)
               if ( iproden .lt. 0 ) then
                iproden = 9
               else if ( iproden .gt. nproden ) then
                iproden = nproden + 8
                if( noverproden .le. noverprodenlim ) then
                 noverproden = noverproden + 1
                 write(*,*) "Warning : A value above the upper ",
     &                "limit of the specified interval of the ",
     &                "probability density function has been ",
     &                "tallied."
                 if( noverproden .gt. noverprodenlim )
     &                write(*,*) "This message is not shown anymore."
                endif
               else
                iproden = iproden + 8
               end if
               tr(ip,ie,it,ir,im,iproden)
     &              = tr(ip,ie,it,ir,im,iproden) + 1

              end if

             end do
             end do
             end do
             end do
             end do

            end if
c S.H. extstat 2024.3.18

           end if

           trEVENT(:,:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.5.29): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nt,nr,nm) )
             tr0(:,:,:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (ttracreg_crit_ist1)
             tr0(:,:,:,:,:) = tr0(:,:,:,:,:) + trEVENT(:,:,:,:,:)
!$OMP END CRITICAL (ttracreg_crit_ist1)
!$OMP BARRIER

!$OMP MASTER
             tr(:,:,:,:,:,1) = tr(:,:,:,:,:,1) + tr0(:,:,:,:,:) / maxcas
             tr(:,:,:,:,:,2) = tr(:,:,:,:,:,2)
     &                     + ( tr0(:,:,:,:,:) / maxcas ) ** 2
c
c sumover
c tr0(np,ne,nt,nr,nm)
             call ttracreg_sumover(m,maxcas,
     &                   np,    ne,    nt,    nr,    nm,    tr0)
c

c S.H. extstat 2024.3.18
            if ( mftal .ge. 5 ) then
             tr(:,:,:,:,:,3) = tr(:,:,:,:,:,3)
     &                     + ( tr0(:,:,:,:,:) / maxcas ) ** 3
             tr(:,:,:,:,:,4) = tr(:,:,:,:,:,4)
     &                     + ( tr0(:,:,:,:,:) / maxcas ) ** 4
            end if
c S.H. extstat 2024.3.18

c S.H. extstat 2024.3.18
            if ( mftal .gt. 5 ) then

             iprodenmnmx = iprodenhead(m) - 1
             do im = 1, nm
             do ir = 1, nr
             do it = 1, nt
             do ie = 1, ne
             do ip = 1, np
               iprodenmnmx = iprodenmnmx + 1

              score = tr0(ip,ie,it,ir,im) / maxcas
              if ( score .gt. 0d0 ) then

               if ( itprodenchk(m) .eq. 0 ) then
                if ( score .lt. tr(ip,ie,it,ir,im,6) ) then
                   tr(ip,ie,it,ir,im,6) = score/10d0
                   prodenmnmx(1,iprodenmnmx) = score/10d0
                 do iproden = 1, nproden
                    tr(ip,ie,it,ir,im,iproden+8) = 0d0
                 end do
                end if
                if ( score .gt. tr(ip,ie,it,ir,im,7) ) then
                   tr(ip,ie,it,ir,im,7) = score*10d0
                   prodenmnmx(2,iprodenmnmx) = score*10d0
                 do iproden = 1, nproden
                    tr(ip,ie,it,ir,im,iproden+8) = 0d0
                 end do
                end if
               end if

               prodenmn = prodenmnmx(1,iprodenmnmx)
               prodenmx = prodenmnmx(2,iprodenmnmx)

               dproden = dlog(prodenmx/prodenmn) / dble(nproden)
               iproden = idnint(dlog(score/prodenmn)/dproden)
               if ( iproden .lt. 0 ) then
                iproden = 9
               else if ( iproden .gt. nproden ) then
                iproden = nproden + 8
                if( noverproden .le. noverprodenlim ) then
                 noverproden = noverproden + 1
                 write(*,*) "Warning : A value above the upper ",
     &                "limit of the specified interval of the ",
     &                "probability density function has been ",
     &                "tallied."
                 if( noverproden .gt. noverprodenlim )
     &                write(*,*) "This message is not shown anymore."
                endif
               else
                iproden = iproden + 8
               end if
               tr(ip,ie,it,ir,im,iproden)
     &              = tr(ip,ie,it,ir,im,iproden) + 1

              end if

             end do
             end do
             end do
             end do
             end do

            end if
c S.H. extstat 2024.3.18

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &              ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) ) then

c to avoid restrictions by counter funciton when this tally is t-track part
c of t-dchain and ndata is specified in the counter.
                     idchainax = 0
                     do iax = 1, itfln(m)
                        if ( itaxs(m,iax) .eq. 15 ) idchainax = 1
                     end do
                     ndatcount = 0
                     if ( idchainax .eq. 1 ) then
                        kdsm = kcont(i)
                        ldsm = 22
                        ndatcount = idas(kdsm+ldsm)
                     end if
                     if ( ndatcount .eq. 0 ) return

                  end if

                end if

            end do

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 ) return

*-----------------------------------------------------------------------
cc H.Iwase 2015/4/2 for electrons
cc                  change the step energy to coutinuous energy
*-----------------------------------------------------------------------
                mat1 = 0
            if( mntsc .gt. 0 .and.
     &          ntscell( idgr(iblz(ibkblz+no,ipomp+1)) ) .ne. 0 .and.
     &        ( ityp .eq. 12 .or. ityp .eq. 13 ) .and.
     &        ( e(ibke+no,ipomp+1) .le. etsmax .and.
     &          e(ibke+no,ipomp+1) .ge. etsmin ) )
     &           mat1 = ntscell( idgr(iblz(ibkblz+no,ipomp+1)) )

      if( ( ityp.eq.12 .or. ityp.eq.13 ) .and.
     .   (( mat1 .eq. 0 )                .or.
     .    ( mat1 .ne. 0 .and. e(ibke+no,ipomp+1) .gt. etsmax ))  )then
      else
           deinit     = 0.d0
           denstepold = 0.d0
           denstepnew = 0.d0
      endif

      if( ityp.eq.12 .or. ityp.eq.13 )then

         e1 =  e(ibke  +no,ipomp+1) - deinit  + denstepold
         e2 = ec(ibkec +no,ipomp+1) - deinit  + denstepnew

         if( e1 .lt. eb(1)    ) return
         if( e2 .ge. eb(ne+1) ) return

         tparti = abs(t(ibkt+no,ipomp+1))
         tpartf = abs(tc(ibktc+no,ipomp+1))
         if( tparti .ge. tb(nt+1) ) return
         if( tpartf .lt. tb(1) ) return

          e(ibke +no,ipomp+1) = e1
         ec(ibkec+no,ipomp+1) = e2

      endif

*-----------------------------------------------------------------------

      if( iMeVperu.eq.1 .and. ityp.ge.15 .and. ityp.le.19 ) then
           ebm = ktyp - ktyp / 1000000 * 1000000
      else
           ebm = 1.d0
      end if

*-----------------------------------------------------------------------
*        check of energy
*-----------------------------------------------------------------------

               if( e(ibke+no,ipomp+1)   .lt. eb(1)*ebm ) goto 999
               if( ec(ibkec+no,ipomp+1) .ge. eb(ne+1)*ebm ) goto 999

*-----------------------------------------------------------------------
*           check of time
*-----------------------------------------------------------------------

               tparti = abs(t(ibkt+no,ipomp+1))
               tpartf = abs(tc(ibktc+no,ipomp+1))

               if( tparti .ge. tb(nt+1) ) goto 999
               if( tpartf .lt. tb(1) ) goto 999

*-----------------------------------------------------------------------
*           check region
*-----------------------------------------------------------------------

                  jj = 0

               do ii = 1, nr

                  call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

                  if( icc .ne. 0 ) goto 501

              end do

                  goto 999

  501         continue

*-----------------------------------------------------------------------
*           track length and initial time
*-----------------------------------------------------------------------

               tlngth = sqrt( ( xc(ibkxc+no,ipomp+1) -
     &                                          x(ibkx+no,ipomp+1) )**2
     &                      + ( yc(ibkyc+no,ipomp+1) -
     &                                          y(ibky+no,ipomp+1) )**2
     &                      + ( zc(ibkzc+no,ipomp+1) -
     &                                         z(ibkz+no,ipomp+1) )**2 )

*-----------------------------------------------------------------------
*           initial and final energy
*-----------------------------------------------------------------------

               do i = 1, ne

                  if( e(ibke+no,ipomp+1) .ge. eb(i)*ebm .and.
     &                e(ibke+no,ipomp+1) .lt. eb(i+1)*ebm ) goto 30

               end do

   30             ie1 = min( i, ne )

               do i = ne, 1, -1

                  if( ec(ibkec+no,ipomp+1) .ge. eb(i)*ebm .and.
     &                ec(ibkec+no,ipomp+1) .lt. eb(i+1)*ebm ) goto 40

               end do

   40             ie2 = max( i, 1 )

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

               rrl = tlngth
               rrr = tlngth
               rrt = 0.0d0
               tpc = tparti

            if( jtyp .ne. 0 .and. mat .gt. 0 ) then

                  call rainge(e(ibke+no,ipomp+1),rng0,
     &                             mat,ityp,ktyp,jtyp,rtyp)

                  rng1 = max( 0.0d0, rng0 - tlngth )

               if( e(ibke+no,ipomp+1) .gt. eb(ne+1)*ebm ) then

                  call rainge(eb(ne+1)*ebm,rngm,mat,ityp,ktyp,jtyp,rtyp)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

                     dst = max( 0.0d0, rng0 - rngm )
                     erg = ( e(ibke+no,ipomp+1) + eb(ne+1)*ebm ) / 2.0
                     tmd = 0.0d0

                  if( erg .gt. 0.1 .or. rtyp .eq. 0.0d0 ) then

                     tmd = dst * ( erg + rtyp )
     &                   / sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                   / rlit

                  else if( erg .gt. 0.0 ) then

                     tmd = dst * sqrt( rtyp / 2.0 / erg ) / rlit

                  end if

                     tpc = tpc + tmd

               end if

            end if

               rrl0 = rrl
               rrr0 = rrr
               rrt0 = rrt
               tpi0 = tpc

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

                  jj = 0

*-----------------------------------------------------------------------

      do 100 ii = 1, nr

*-----------------------------------------------------------------------

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 100

               ir = ii

               icli = idgr(iblz1)

*-----------------------------------------------------------------------

               tpi = tpi0
               rrl = rrl0
               rrr = rrr0
               rrt = rrt0

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 270 ie = ie1, ie2, -1

                     emie = max( ec(ibkec+no,ipomp+1), eb(ie)*ebm )
                     emiu = min( e(ibke+no,ipomp+1), eb(ie+1)*ebm )
                     erg  = ( emiu + emie ) / 2.0

                     call fmfac(m,icli,erg,oldwt,facm)

                  if( jtyp .ne. 0 .and. mat .gt. 0 ) then

                     call rainge(emie,rng,mat,ityp,ktyp,jtyp,rtyp)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

*-----------------------------------------------------------------------

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                 ec(ibkec+no,ipomp+1) .gt. eb(ie)*ebm ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

*-----------------------------------------------------------------------

                  end if

*-----------------------------------------------------------------------
*              initial and final time
*-----------------------------------------------------------------------

               dst = rrl
               tmd = 0.0d0
               CC  = 0.0d0

               if(erg.gt.0.0 .or. rtyp.gt.0.0) then ! T.Sato 2021/05/08 to avoid NaN

                if( erg .gt. 0.1 .or. rtyp .eq. 0.0d0 ) then

                  tmd = dst * ( erg + rtyp )
     &                / sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                / rlit
                  CC  = 1.d0 / ( erg + rtyp )
     &                * sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                * rlit

                else if( erg .gt. 0.0 ) then

                  tmd = dst * sqrt( rtyp / 2.0 / erg ) / rlit
                  CC = 1.d0 / sqrt( rtyp / 2.0 / erg ) * rlit

                end if

               endif

               tpf = tpi + tmd

               do 271 it = 1, nt

                 if( tpf .lt. tb(it) .or. tpi .ge. tb(it+1) ) goto 271

                 tin = max( tpi, tb(it) )
                 tfn = min( tpf, tb(it+1) )
                 tmd = max( 0.0d0, tfn - tin )

                 dst = tmd * CC

*-----------------------------------------------------------------------

                     tlv = oldwt * dst

                  do im = 1, nm
                  do ip = 1, ipn

!OBINATA(2012.5.29): Ct = Ct + xi.wi
                     trEVENT(ips(ip),ie,it,ir,im) =
     &               trEVENT(ips(ip),ie,it,ir,im) + tlv * facm(im)

                  end do
                  end do

*-----------------------------------------------------------------------

  271          continue

                  rrr = rrr - rrl
                  tpi = tpf

  270       continue

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------
cc H.Iwase 2015/4/2 for electrons
cc                  change the continuous energy back to the step energy

  999 if( ityp.eq.12 .or. ityp.eq.13 )then

          e(ibke +no,ipomp+1) =
     &                    e(ibke +no,ipomp+1) + deinit  - denstepold
         ec(ibkec+no,ipomp+1) =
     &                    ec(ibkec+no,ipomp+1) + deinit  - denstepnew

      endif

*-----------------------------------------------------------------------

      return
      end



************************************************************************
*                                                                      *
      subroutine ttractet(ncol,m,nl,lt,np,nr,mr,
     &                    ne,nm,nt,mftal,kr,eb,tb,tr,
     &                    trEVENT)
*                                                                      *
*       track length tally in tetra mesh                               *
*       Modified by T.Furuta on 2025/01/16                             *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              0 : end of batch                                        *
*              4 : source particle                                     *
*                                                                      *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt, itpan, itpat, jtpat ! frtati 2021/10/05
!$    use omp_lib
*-----------------------------------------------------------------------
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

      parameter( rlit = 29.97925d0 )

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)

*-----------------------------------------------------------------------
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100
      common /cntreg/ ncntc(3), ncreg(3), incrc(3), incrt(3), kcont(3)
      dimension     idas(1)
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)
      common /regdc/  idrg(kvlmax), idgr(kvmmax)

      common /tall82/ itcnth(9,itlmax)

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   tb(nt+1)
c$$$      dimension   tr(np,ne,nt,nr,nm,2)
      dimension   tr(np,ne,nt,nr,nm,mftal) ! S.H. extstat 2024.3.13
      dimension   trEVENT(np,ne,nt,nr,nm)       !OBINATA(2012.5.29): as Ct
      real(8),allocatable,save:: tr0(:,:,:,:,:) !OBINATA(2012.5.29): as C

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension facm(6)

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /egs5cmn10/denstepold,denstepnew,deinit
      real*8            denstepold,denstepnew,deinit
!$OMP THREADPRIVATE(/egs5cmn10/)


      common /  tscmsg   / ktsc(kvlmax), mntsc, ntsc(kvlmax)
      common /  tscreg   / ntscell(kvlmax)
      common / etsminmax / etsmin, etsmax

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      integer iii0,kkk0
      common /itettal2/ iii0,kkk0
!$OMP THREADPRIVATE(/itettal2/)

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.5.29): change tr(,,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,:,:,1) = tr(:,:,:,:,:,1) + trEVENT(:,:,:,:,:)
             tr(:,:,:,:,:,2) = tr(:,:,:,:,:,2) + trEVENT(:,:,:,:,:) ** 2

! sumover
             call ttracreg_sumover(m,1,
     &                   np,    ne,    nt,    nr,    nm,    trEVENT)

           end if

           trEVENT(:,:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.5.29): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nt,nr,nm) )
             tr0(:,:,:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (ttractet_crit_ist1)
             tr0(:,:,:,:,:) = tr0(:,:,:,:,:) + trEVENT(:,:,:,:,:)
!$OMP END CRITICAL (ttractet_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,:,:,1) = tr(:,:,:,:,:,1) + tr0(:,:,:,:,:) / maxcas
             tr(:,:,:,:,:,2) = tr(:,:,:,:,:,2)
     &                     + ( tr0(:,:,:,:,:) / maxcas ) ** 2

! sumover
             call ttracreg_sumover(m,maxcas,
     &                   np,    ne,    nt,    nr,    nm,    tr0)

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &              ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) ) then

c to avoid restrictions by counter funciton when this tally is t-track part
c of t-dchain and ndata is specified in the counter.
                     idchainax = 0
                     do iax = 1, itfln(m)
                        if ( itaxs(m,iax) .eq. 15 ) idchainax = 1
                     end do
                     ndatcount = 0
                     if ( idchainax .eq. 1 ) then
                        kdsm = kcont(i)
                        ldsm = 22
                        ndatcount = idas(kdsm+ldsm)
                     end if
                     if ( ndatcount .eq. 0 ) return

                  end if

               end if

            end do

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 ) return

*-----------------------------------------------------------------------
cc H.Iwase 2015/4/2 for electrons
cc                  change the step energy to coutinuous energy
*-----------------------------------------------------------------------
                mat1 = 0
            if( mntsc .gt. 0 .and.
     &          ntscell( idgr(iblz(ibkblz+no,ipomp+1)) ) .ne. 0 .and.
     &        ( ityp .eq. 12 .or. ityp .eq. 13 ) .and.
     &        ( e(ibke+no,ipomp+1) .le. etsmax .and.
     &          e(ibke+no,ipomp+1) .ge. etsmin ) )
     &           mat1 = ntscell( idgr(iblz(ibkblz+no,ipomp+1)) )

      if( ( ityp.eq.12 .or. ityp.eq.13 ) .and.
     .   (( mat1 .eq. 0 )                .or.
     .    ( mat1 .ne. 0 .and. e(ibke+no,ipomp+1) .gt. etsmax ))  )then
      else
           deinit     = 0.d0
           denstepold = 0.d0
           denstepnew = 0.d0
      endif

      if( ityp.eq.12 .or. ityp.eq.13 )then

         e1 =  e(ibke  +no,ipomp+1) - deinit  + denstepold
         e2 = ec(ibkec +no,ipomp+1) - deinit  + denstepnew

         if( e1 .lt. eb(1)    ) return
         if( e2 .ge. eb(ne+1) ) return

         tparti = abs(t(ibkt+no,ipomp+1))
         tpartf = abs(tc(ibktc+no,ipomp+1))
         if( tparti .ge. tb(nt+1) ) return
         if( tpartf .lt. tb(1) ) return

          e(ibke +no,ipomp+1) = e1
         ec(ibkec+no,ipomp+1) = e2

      endif

*-----------------------------------------------------------------------

      if( iMeVperu.eq.1 .and. ityp.ge.15 .and. ityp.le.19 ) then
           ebm = ktyp - ktyp / 1000000 * 1000000
      else
           ebm = 1.d0
      end if

*-----------------------------------------------------------------------
*        check of energy
*-----------------------------------------------------------------------

               if( e(ibke+no,ipomp+1)   .lt. eb(1)*ebm ) goto 999
               if( ec(ibkec+no,ipomp+1) .ge. eb(ne+1)*ebm ) goto 999

*-----------------------------------------------------------------------
*           check of time
*-----------------------------------------------------------------------

               tparti = abs(t(ibkt+no,ipomp+1))
               tpartf = abs(tc(ibktc+no,ipomp+1))

               if( tparti .ge. tb(nt+1) ) goto 999
               if( tpartf .lt. tb(1) ) goto 999

*-----------------------------------------------------------------------
*           check region and tetra
*-----------------------------------------------------------------------

               jj = 0

               ic=idgr(iblz1)
               itet=kkk0-10000
               ihelem=iii0

               call ttetck(ic,mr,kr,itet,ihelem,ir,icc)

               if( icc .ne. 1 ) goto 999

*-----------------------------------------------------------------------
*           track length and initial time
*-----------------------------------------------------------------------

               tlngth = sqrt( ( xc(ibkxc+no,ipomp+1) -
     &                                         x(ibkx+no,ipomp+1) )**2
     &                      + ( yc(ibkyc+no,ipomp+1) -
     &                                         y(ibky+no,ipomp+1) )**2
     &                      + ( zc(ibkzc+no,ipomp+1) -
     &                                         z(ibkz+no,ipomp+1) )**2 )

*-----------------------------------------------------------------------
*           initial and final energy
*-----------------------------------------------------------------------

               do i = 1, ne

                  if( e(ibke+no,ipomp+1) .ge. eb(i)*ebm .and.
     &                e(ibke+no,ipomp+1) .lt. eb(i+1)*ebm ) goto 30

               end do

   30             ie1 = min( i, ne )

               do i = ne, 1, -1

                  if( ec(ibkec+no,ipomp+1) .ge. eb(i)*ebm .and.
     &                ec(ibkec+no,ipomp+1) .lt. eb(i+1)*ebm ) goto 40

               end do

   40             ie2 = max( i, 1 )

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

               rrl = tlngth
               rrr = tlngth
               rrt = 0.0d0
               tpc = tparti

            if( jtyp .ne. 0 .and. mat .gt. 0 ) then

                  call rainge(e(ibke+no,ipomp+1),
     &                         rng0,mat,ityp,ktyp,jtyp,rtyp)

                  rng1 = max( 0.0d0, rng0 - tlngth )

               if( e(ibke+no,ipomp+1) .gt. eb(ne+1)*ebm ) then

                  call rainge(eb(ne+1)*ebm,rngm,mat,ityp,ktyp,jtyp,rtyp)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

                     dst = max( 0.0d0, rng0 - rngm )
                     erg = ( e(ibke+no,ipomp+1) + eb(ne+1)*ebm ) / 2.0
                     tmd = 0.0d0

                  if( erg .gt. 0.1 .or. rtyp .eq. 0.0d0 ) then

                     tmd = dst * ( erg + rtyp )
     &                   / sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                   / rlit

                  else if( erg .gt. 0.0 ) then

                     tmd = dst * sqrt( rtyp / 2.0 / erg ) / rlit

                  end if

                     tpc = tpc + tmd

               end if

            end if

               rrl0 = rrl
               rrr0 = rrr
               rrt0 = rrt
               tpi0 = tpc

*-----------------------------------------------------------------------

               icli = idgr(iblz1)

*-----------------------------------------------------------------------

               tpi = tpi0
               rrl = rrl0
               rrr = rrr0
               rrt = rrt0

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 270 ie = ie1, ie2, -1

                     emie = max( ec(ibkec+no,ipomp+1), eb(ie)*ebm )
                     emiu = min( e(ibke+no,ipomp+1), eb(ie+1)*ebm )
                     erg  = ( emiu + emie ) / 2.0

                     call fmfac(m,icli,erg,oldwt,facm)

                  if( jtyp .ne. 0 .and. mat .gt. 0 ) then

                     call rainge(emie,rng,mat,ityp,ktyp,jtyp,rtyp)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

*-----------------------------------------------------------------------

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                 ec(ibkec+no,ipomp+1) .gt. eb(ie)*ebm ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

*-----------------------------------------------------------------------

                  end if

*-----------------------------------------------------------------------
*              initial and final time
*-----------------------------------------------------------------------

               dst = rrl
               tmd = 0.0d0
               CC  = 0.0d0

               if( erg .gt. 0.1 .or. rtyp .eq. 0.0d0 ) then

                  tmd = dst * ( erg + rtyp )
     &                / sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                / rlit
                  CC  = 1.d0 / ( erg + rtyp )
     &                * sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                * rlit

               else if( erg .gt. 0.0 ) then

                  tmd = dst * sqrt( rtyp / 2.0 / erg ) / rlit
                  CC = 1.d0 / sqrt( rtyp / 2.0 / erg ) * rlit

               end if

               tpf = tpi + tmd

               do 271 it = 1, nt

                 if( tpf .lt. tb(it) .or. tpi .ge. tb(it+1) ) goto 271

                 tin = max( tpi, tb(it) )
                 tfn = min( tpf, tb(it+1) )
                 tmd = max( 0.0d0, tfn - tin )

                 dst = tmd * CC

*-----------------------------------------------------------------------

                     tlv = oldwt * dst

                  do im = 1, nm
                  do ip = 1, ipn

!OBINATA(2012.5.29): Ct = Ct + xi.wi
                     trEVENT(ips(ip),ie,it,ir,im) =
     &               trEVENT(ips(ip),ie,it,ir,im) + tlv * facm(im)

                  end do
                  end do

*-----------------------------------------------------------------------

  271          continue

                  rrr = rrr - rrl
                  tpi = tpf

  270       continue

*-----------------------------------------------------------------------
cc H.Iwase 2015/4/2 for electrons
cc                  change the continuous energy back to the step energy

  999 if( ityp.eq.12 .or. ityp.eq.13 )then

          e(ibke +no,ipomp+1) =  e(ibke +no,ipomp+1) +
     &                                    deinit  - denstepold
         ec(ibkec+no,ipomp+1) = ec(ibkec+no,ipomp+1) +
     &                                    deinit  - denstepnew

      endif

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine ptracreg(m,np,nr,mr,ne,nm,nt,mftal,kr,eb,tb,tr,
     &                    nvl,ivl,rvl,
     &                    nx,ny,nz,xm,ym,zm,igsh,idasa)
*                                                                      *
*       output the track length tally in region mesh                   *
*       last modified by D.OBINATA on 2012/04/24                       *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use TDCHAINMOD, only: fflux,itnm2tdc,itdc2reg,check_itdc2reg !FURUTA20200601
      use partmod ! frtati 2021/10/05
      use moddas_tally
      use talmod, only: deist ! S.H. 2022.12.16
*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

      common /stat / istdev, irestart, ireschk
      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax) ! S.H. 2022.12.23

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall21/ rtfac(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &                itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &                itmpn(itlmax,6), itmpt(itlmax,6,6,2)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall49/ itglt(itlmax)

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /volreg/ dvol(kvlmax)

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

*-----------------------------------------------------------------------
      common /tall78/ itism(itlmax), itist(10,itlmax), itjst(10,itlmax),
     &                itkst(10,itlmax), itstt(itlmax), itsdd(itlmax)

      common /tall93/ tprodenmn(itlmax), tprodenmx(itlmax),
     &     nbtproden(itlmax), itprodenchk(itlmax) !S.H. extstat 2024.4.28

      dimension idas(mdas*2) !2022.12.1 S.H. temporary for fbounds-check
      equivalence ( das, idas )

      common /istcut/ ist_cut, ist_bat
*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   ew(ne)
      dimension   tb(nt+1)
      dimension   tw(nt)
      dimension   vl(nr)
      dimension   lr(nr)
      dimension   tr(np,ne,nt,nr,nm,mftal) ! S.H. extstat 2024.3.13
      dimension   ivl(nvl)
      dimension   rvl(nvl)

      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   val(nr)

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------

      dimension tott(np,2) ! frtati 2021/10/05 6 -> np

      character hsunit(14)*29

      data hsunit( 1) / '[1/cm^2/source]              '/
      data hsunit( 2) / '[1/cm^2/MeV/source]          '/
      data hsunit( 3) / '[1/cm^2/Lethargy/source]     '/
      data hsunit( 4) / '[cm/source]                  '/
      data hsunit(11) / '[1/cm^2/nsec/source]         '/
      data hsunit(12) / '[1/cm^2/nsec/MeV/source]     '/
      data hsunit(13) / '[1/cm^2/nsec/Lethargy/source]'/
      data hsunit(14) / '[cm/nsec/source]             '/

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      character cha*1
      data cha /"'"/

      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31

*-----------------------------------------------------------------------
      character(28) cfmt                !FURUTA20200601
      character(12) cir                 !FURUTA20200601
      common /redufmt/ iredufmt(itlmax) !FURUTA20200601
*-----------------------------------------------------------------------
      character rpa*1
      data rpa /'}'/
      character yen*1

c S.H. extstat 2024.3.18
      character cpass*3, cyes*3, cno*3
      data cyes /'yes'/
      data cno /' no'/
      real*8 critpass
      data critpass / 0.05 / ! criterion to pass statistical check
c S.H. extstat 2024.3.18

cnais 2023/01/31
      include 'samepage_include/samepage000.inc'

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

      include 'samepage_include/samepage001.inc'


*-----------------------------------------------------------------------

      if ( iMeVperu.eq. 1 ) then
         hsunit( 2) = '[1/cm^2/(MeV/n)/source]      '
         hsunit(12) = '[1/cm^2/nsec/(MeV/n)/source] '
      end if

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------

      if ( npe .le. 1 ) then
         nstepbch = 1
         ncurrbch = nobch
      else ! when MPI
         nstepbch = npe-1
         ncurrbch = nobch/(npe-1)
      end if
      nproden = nbtproden(m) !  bin number for probability density function

*-----------------------------------------------------------------------
*     for igshow
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

            npg = np
            neg = ne
            ntg = nt

         else

            npg = 1
            neg = 1
            ntg = 1

         end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1,4 11,14: /cm^2/source
*                                 /cm^2/sec/source
*                    = 2   12   : /cm^2/MeV/source
*                                 /cm^2/MeV/nsec/source
*                    = 3   13   : /cm^2/Lethargy/source
*                                 /cm^2/Lethargy/nsec/source
*-----------------------------------------------------------------------

            if( itunt(m) .eq.  1 .or. itunt(m) .eq.  4 .or.
     &          itunt(m) .eq. 11 .or. itunt(m) .eq. 14 ) then

               do i = 1, ne

                  ew(i) = 1.d+0

               end do
               ew_sum = 1.0

            else if( itunt(m) .eq. 2 .or. itunt(m) .eq. 12 ) then

               do i = 1, ne

                  ew(i) = eb(i+1) - eb(i)

               end do
               ew_sum = eb(ne+1) -eb(1)

            else if( itunt(m) .eq. 3 .or. itunt(m) .eq. 13 ) then

               do i = 1, ne

                  ew(i) = log( eb(i+1) / eb(i) )

               end do
               ew_sum = log(eb(ne+1) -eb(1))

            end if

*-----------------------------------------------------------------------
*           itunt(m) = 11, 12, 13, 14 : /.../nsec/source
*-----------------------------------------------------------------------

            if( itunt(m) .gt. 10 ) then

               do i = 1, nt

                  tw(i) = tb(i+1) - tb(i)

               end do
               tw_sum = tb(nt+1) - tb(1)

            else

               do i = 1, nt

                  tw(i) = 1.d+0

               end do
               tw_sum = 1.0

            end if

*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)
               vl_sum = sum(vl(1:nr))

*-----------------------------------------------------------------------
*        ( unit = 4 or 14  ; vol = 1.0 )
*-----------------------------------------------------------------------

            if( itunt(m) .eq. 4 .or. itunt(m) .eq. 14 ) then

               do ir = 1, nr

                  vl(ir) = 1.0d0

               end do
               vl_sum = 1.0

            end if

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

                  c1 = 1.0d+0 / rsouin

               else

                  c1 = 0d0

               end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do 101 im = 1, nm
               do 101 ir = 1, nr
               do 101 it = 1, nt
               do 101 ie = 1, ne
               do 101 ip = 1, np

                  if( tr(ip,ie,it,ir,im,1) .gt. 0.d0 ) then

                     fmaxfc = tr(ip,ie,it,ir,im,1)
     &                                   / vl(ir) / ew(ie) / tw(it)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

  101          continue

            end if

            if ( mftal .ge. 5 ) call timex(time3,time2,9) ! S.H. extstat 2024.3.22

            do 100 im = 1, nm
            do 100 ir = 1, nr
            do 100 it = 1, nt
            do 100 ie = 1, ne
            do 100 ip = 1, np

               if( tr(ip,ie,it,ir,im,1) .gt. 0.d0 ) then

c S.H. extstat 2024.3.18
                if ( mftal .lt. 5 ) then
                  call calc_stdev(m,Xa,sigx,
     &                            tr(ip,ie,it,ir,im,1),
     &                            tr(ip,ie,it,ir,im,2),
     &             abs(rtfac(m)/facmax(m))/vl(ir)/ew(ie)/tw(it))
                else
                  call calc_stdev_ext(m,Xa,sigx,X3,VOV,
     &                            tr(ip,ie,it,ir,im,1),
     &                            tr(ip,ie,it,ir,im,2),
     &                            tr(ip,ie,it,ir,im,3),
     &                            tr(ip,ie,it,ir,im,4),
     &             abs(rtfac(m)/facmax(m))/vl(ir)/ew(ie)/tw(it))
                end if
c S.H. extstat 2024.3.18

                  tr(ip,ie,it,ir,im,1) = Xa
                  tr(ip,ie,it,ir,im,2) = sigx

c S.H. extstat 2024.3.18
                if ( mftal .ge. 5 ) then
                  tr(ip,ie,it,ir,im,3) = X3
                  tr(ip,ie,it,ir,im,4) = VOV
                  if ( sigx.gt.0d0 .and. time2.gt.0d0 ) then
                     tr(ip,ie,it,ir,im,5) = 1d0/(sigx**2*time2/60d0)
                  else
                     tr(ip,ie,it,ir,im,5) = 0d0
                  end if
                end if
c S.H. extstat 2024.3.18

cKN 2016/12/31
                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ip,ie,it,ir,im,1) .gt. cmax )
     &                        cmax = tr(ip,ie,it,ir,im,1)

                  if( tr(ip,ie,it,ir,im,1) .lt. cmin )
     &                        cmin = tr(ip,ie,it,ir,im,1)

               else

                  isdz = 1
                  tr(ip,ie,it,ir,im,2) = 0.0

               end if

! sumover
               fact_in = abs(rtfac(m)/facmax(m))
               call ptracreg_sumover_stdev(0,m,ip,ie,it,ir,im,
     &                           fact_in,ew(ie),tw(it),vl(ir),
     &                                  ew_sum,tw_sum,vl_sum)

  100       continue

            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

         end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

            noe  = 1
            nerr = 0

         if( igsh .eq. 0 .and. itall .eq. 3 .and.
     &       itism(m) .gt. 0 ) then

            noe  = noe + 1

         end if

*-----------------------------------------------------------------------

        do 900 ioe = 1, noe

         if( igsh .ne. 0 .and.
     &     ( itaxs(m,iax) .lt. 7 .or.
     &       itrsh(m) .eq. 0 ) ) goto 900

*-----------------------------------------------------------------------

             nstd = 0

         if ( ioe .eq. 1 ) then

            if( (itall .eq. 2 .and. nobch .lt. maxbch .and. igsh .eq. 0)
     &           .or. ( itall .eq. 4 .and. igsh .eq. 0 ) ) then

               call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &              nobch,maxbch,npe)

            else

               fname = ctfln(m,iax)

            end if

         else if ( ioe .eq. 2 ) then

            if( itall. eq. 3 .and. itism(m) .gt. 0 ) then

              call mk_2distfn(ctfln(m,iax),fname,itfll(m,iax))
              nstd = 1

            else

              goto 900

            end if

         end if

*-----------------------------------------------------------------------

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------

            gfnam = ctfln(m,iax)
            igfmn = itfll(m,iax)
            igser = itger(m)

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

               call trckech(iot,m,iax,1)

*-----------------------------------------------------------------------

         if( nstd .eq. 1 ) then

            if ( m .le. 1 ) then
               initdeist = 0
            else
               initdeist = sum(itism(1:m-1))
            end if

               inum = 0

            do i1  = 1, itist(1,m)
            do i2  = 1, itist(2,m)
            do i3  = 1, itist(3,m)
            do i4  = 1, itist(4,m)
            do i5  = 1, itist(5,m)
            do i6  = 1, itist(6,m)
            do i7  = 1, itist(7,m)
            do i8  = 1, itist(8,m)
            do i9  = 1, itist(9,m)
            do i10 = 1, itist(10,m)

               inum = inum + 1

               ig = idas( itstt(m) + itjst(1,m) + i1 )
               ix = idas( itstt(m) + itjst(2,m) + i2 )
               iy = idas( itstt(m) + itjst(3,m) + i3 )
               iz = idas( itstt(m) + itjst(4,m) + i4 )
               ir = idas( itstt(m) + itjst(5,m) + i5 )
               ie = idas( itstt(m) + itjst(6,m) + i6 )
               it = idas( itstt(m) + itjst(7,m) + i7 )
               ia = idas( itstt(m) + itjst(8,m) + i8 )
               ip = idas( itstt(m) + itjst(9,m) + i9 )
               im = idas( itstt(m) + itjst(10,m) + i10 )

               deist( 1,
     &              initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &              = tr(ip,ie,it,ig,im,1)
               deist( 2,
     &              initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &              = tr(ip,ie,it,ig,im,2)

c S.H. extstat 2024.3.18
              if ( mftal .ge. 5 ) then
                 deist( 3,
     &                initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &                = tr(ip,ie,it,ig,im,4)
                 deist( 4,
     &                initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &                = tr(ip,ie,it,ig,im,5)
              end if
c S.H. extstat 2024.3.18

c S.H. extstat 2024.3.19
            if ( mftal .ge. 5 ) then
               nobchhalf = int( ncurrbch/2 )
             if ( nobchhalf.gt.1 ) then
               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilin
     &         = dble(i)
               yilin
     &         = deist(1,initdeist+(i-1)*sum(itism(1:itnm))+inum)
               sumxi = sumxi + xilin
               sumyi = sumyi + yilin
               sumxyi = sumxyi + xilin*yilin
               sumxi2 = sumxi2 + xilin*xilin
              end do
               slopemean = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )
               slopemean = slopemean
     &         / deist(1,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)

               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
               facls
     &         = deist(2,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &         * dsqrt(dble(ncurrbch))
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilog
     &         = dlog(dble(i))
               yilog
     &         = dlog(deist(2,initdeist+(i-1)*sum(itism(1:itnm))+inum)
     &         / facls )
               sumxi = sumxi + xilog
               sumyi = sumyi + yilog
               sumxyi = sumxyi + xilog*yilog
               sumxi2 = sumxi2 + xilog*xilog
              end do
               powerrele = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )

               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
               facls
     &         = deist(3,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &         * dble(ncurrbch)
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilog
     &         = dlog(dble(i))
               yilog
     &         = dlog(deist(3,initdeist+(i-1)*sum(itism(1:itnm))+inum)
     &         / facls )
               sumxi = sumxi + xilog
               sumyi = sumyi + yilog
               sumxyi = sumxyi + xilog*yilog
               sumxi2 = sumxi2 + xilog*xilog
              end do
               powervov = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )

               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilin
     &         = dble(i)
               yilin
     &         = deist(4,initdeist+(i-1)*sum(itism(1:itnm))+inum)
               sumxi = sumxi + xilin
               sumyi = sumyi + yilin
               sumxyi = sumxyi + xilin*yilin
               sumxi2 = sumxi2 + xilin*xilin
              end do
               slopefom = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )
               slopefom = slopefom
     &         / deist(4,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
             else
              slopemean = 0d0
              powerrele = 0d0
              powervov = 0d0
              slopefom = 0d0
             end if
            end if
c S.H. extstat 2024.3.19

c S.H. extstat 2024.3.18
              if ( mftal .gt. 5 ) then
               prodenmn = tr(ip,ie,it,ig,im,6)
               prodenmx = tr(ip,ie,it,ig,im,7)
!$             prodenmn = tprodenmn(m)/(rtfac(m)/vl(ig)/ew(ie)/tw(it))
!$             prodenmx = tprodenmx(m)/(rtfac(m)/vl(ig)/ew(ie)/tw(it))
               dproden = dlog(prodenmx/prodenmn) / dble(nproden)

               ntotcnt = 0
               do iproden = 1, nproden
                  ntotcnt = ntotcnt + tr(ip,ie,it,ig,im,iproden+8)
               end do

               if ( ntotcnt .gt. 0 ) then
                  do iproden = 1, nproden
                     tr(ip,ie,it,ig,im,iproden+8)
     &                    = tr(ip,ie,it,ig,im,iproden+8)/dble(ntotcnt)
                  end do
               end if
              end if
c S.H. extstat 2024.3.18

c S.H. extstat 2024.3.22
*-----------------------------------------------------------------------

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               ireg = lr(ig)

            if ( mftal .ge. 5 ) then

               write(iot,'("#   no. =",i3,3x,"reg =",i7)')
     &                     inum, ireg

               if( itist(6,m) .gt. 1 ) then
                  write(iot,'(
     &            "#  ie =",i3,/
     &            "#   e = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     it, eb(ie), eb(ie+1)
               end if
               if( itist(7,m) .gt. 1 ) then
                  write(iot,'(
     &            "#  it =",i3,/
     &            "#   t = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     it, tb(it), tb(it+1)
               if( itist(9,m) .gt. 1 )
     &            write(iot,'("#     ip =",i3)') ip
               if( itist(10,m) .gt. 1 )
     &            write(iot,'("#   mset =",i3)') itmnt(m,im)
               end if

c S.H. extstat 2024.4.3
               write(iot,'(/"# Statistical check sheet at batch",i9)')
     &              nobch
               write(iot,'("# Quantity",19x,"Output",21x,"Value",9x,
     &                     "Desired",4x,"Pass")')

               write(iot,'("# Mean",23x,"Current value",13x,1p1e12.4,
     &                   3x,"Constant")')
     &              deist(1,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               if ( dabs(slopemean) .lt. critpass ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("# Mean",23x,"History dep. (rel. slope)",
     &                   1x,0pf8.4,7x,"= 0.00",5x,a3)')
     &                   slopemean, cpass

               if ( deist(2,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              .lt. 0.05d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("# Relative error",13x,"Current value",13x,
     &                   0pf8.4,7x,"< 0.05",5x,3a)')
     &              deist(2,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              , cpass
               if ( dabs(0.5d0+powerrele) .lt. critpass*0.5d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("# Relative error",13x,
     &                   "History dep. (p in N^p)",
     &                   3x,0pf8.4,7x,"= -0.50",4x,a3)')
     &                   powerrele, cpass

               if ( deist(3,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              .lt. 0.10d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("# Variance of the variance",3x,
     &                   "Current value",13x,0pf8.4,7x,"< 0.10",
     &                   5x,3a)')
     &              deist(3,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              , cpass
               write(iot,'("# Variance of the variance",3x,
     &                   "History dep. (p in N^p)",
     &                   3x,0pf8.4,7x,"= -1.00",4x,a3)')
     &                   powervov, cpass

               write(iot,'("# Figure of Merit",12x,"Current value",
     &                   13x,1p1e12.4,3x,"Constant")')
     &              deist(4,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               if ( dabs(slopefom) .lt. critpass ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("# Figure of Merit",12x,
     &                   "History dep. (rel. slope)",
     &                   1x,0pf8.4,7x,"= 0.00",5x,a3)')
     &                   slopefom, cpass

               write(iot,'(/)')
c S.H. extstat 2024.4.3

               write(iot,'("p: notc xtxt(0) ytxt(0)")')
               write(iot,'("p: xfac(1.5) form(0.5) xorg(-0.1)")')
               write(iot,'("p: xmin(0) xmax(1) ymin(0) ymax(1)")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0 0.9")')
               write(iot,'("1.1 0.9")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0.32 0")')
               write(iot,'("0.32 1.1")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0.32 0")')
               write(iot,'("0.32 1.1")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0.65 0")')
               write(iot,'("0.65 1.1")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0.83 0")')
               write(iot,'("0.83 1.1")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0.97 0")')
               write(iot,'("0.97 1.1")')

               write(iot,'("w: Statistical check sheet at batch"
     &                   ,i9,"/ x(0.05) y(1.35) s(2) f(5)")') nobch

               write(iot,'("w: Quantity / x(0.) y(0.95) f(5)")')
               write(iot,'("w: Output / x(0.33) y(0.95) f(5)")')
               write(iot,'("w: Value / x(0.66) y(0.95) f(5)")')
               write(iot,'("w: Desired / x(0.84) y(0.95) f(5)")')
               write(iot,'("w: Pass / x(0.98) y(0.95) f(5)")')

               write(iot,'("w: Mean / x(0.) y(0.8) f(5)")')
               write(iot,'("w: Current value / x(0.33) y(0.8) f(5)")')
               write(iot,'("w: ",1p1e12.4," / x(0.65) y(0.8) f(5)")')
     &              deist(1,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               write(iot,'("w: Constant / x(0.84) y(0.8) f(5)")')

               write(iot,'("w: Mean / x(0.) y(0.7) f(5)")')
               write(iot,'("w: History dep. (rel. slope) "
     &                   ,"/ x(0.33) y(0.7) f(5)")')
               write(iot,'("w: ",0pf8.4," / x(0.65) y(0.7) f(5)")')
     &              slopemean
               write(iot,'("w: = 0.00 / x(0.84) y(0.7) f(5)")')
               if ( dabs(slopemean) .lt. critpass ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("w: ",a3," / x(0.98) y(0.75) f(5)")') cpass

               write(iot,'("w: Relative error / x(0.) y(0.6) f(5)")')
               write(iot,'("w: Current value / x(0.33) y(0.6) f(5)")')
               write(iot,'("w: ",0pf8.4," / x(0.65) y(0.6) f(5)")')
     &              deist(2,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               write(iot,'("w: < 0.05 / x(0.84) y(0.6) f(5)")')
               if ( deist(2,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              .lt. 0.05d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("w: ",a3," / x(0.98) y(0.6) f(5)")') cpass

               write(iot,'("w: Relative error / x(0.) y(0.5) f(5)")')
               write(iot,'("w: History dep. (p in N^p) "
     &                   ,"/ x(0.33) y(0.5) f(5)")')
               write(iot,'("w: ",0pf8.4," / x(0.65) y(0.5) f(5)")')
     &              powerrele
               write(iot,'("w: = -0.50 / x(0.84) y(0.5) f(5)")')
               if ( dabs(0.5d0+powerrele) .lt. critpass*0.5d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("w: ",a3," / x(0.98) y(0.5) f(5)")') cpass

               write(iot,'("w: Variance of the variance "
     &                   ,"/ x(0.) y(0.4) f(5)")')
               write(iot,'("w: Current value / x(0.33) y(0.4) f(5)")')
               write(iot,'("w: ",0pf8.4," / x(0.65) y(0.4) f(5)")')
     &              deist(3,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               write(iot,'("w: < 0.10 / x(0.84) y(0.4) f(5)")')
               if ( deist(3,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              .lt. 0.10d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("w: ",a3," / x(0.98) y(0.4) f(5)")') cpass

               write(iot,'("w: Variance of the variance "
     &                   ,"/ x(0.) y(0.3) f(5)")')
