               call trckech(iot,m,iax,1)

*-----------------------------------------------------------------------

         if( nstd .eq. 1 ) then

            if ( m .le. 1 ) then
               initdeist = 0
            else
               initdeist = sum(itism(1:m-1))
            end if

               inum = 0

            do i1  = 1, itist(1,m)
            do i2  = 1, itist(2,m)
            do i3  = 1, itist(3,m)
            do i4  = 1, itist(4,m)
            do i5  = 1, itist(5,m)
            do i6  = 1, itist(6,m)
            do i7  = 1, itist(7,m)
            do i8  = 1, itist(8,m)
            do i9  = 1, itist(9,m)
            do i10 = 1, itist(10,m)

               inum = inum + 1

               ig = idas( itstt(m) + itjst(1,m) + i1 )
               ix = idas( itstt(m) + itjst(2,m) + i2 )
               iy = idas( itstt(m) + itjst(3,m) + i3 )
               iz = idas( itstt(m) + itjst(4,m) + i4 )
               ir = idas( itstt(m) + itjst(5,m) + i5 )
               ie = idas( itstt(m) + itjst(6,m) + i6 )
               it = idas( itstt(m) + itjst(7,m) + i7 )
               ia = idas( itstt(m) + itjst(8,m) + i8 )
               ip = idas( itstt(m) + itjst(9,m) + i9 )
               im = idas( itstt(m) + itjst(10,m) + i10 )

               deist( 1,
     &              initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &         = tr(ip,ie,it,icf(ir,iz),ia,im,1)
               deist( 2,
     &              initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &         = tr(ip,ie,it,icf(ir,iz),ia,im,2)

c S.H. extstat 2024.3.18
              if ( mftal .ge. 5 ) then
                 deist( 3,
     &                initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &                = tr(ip,ie,it,icf(ir,iz),ia,im,4)
                 deist( 4,
     &                initdeist +(ncurrbch-1)*sum(itism(1:itnm)) +inum )
     &                = tr(ip,ie,it,icf(ir,iz),ia,im,5)
              end if
c S.H. extstat 2024.3.18

c S.H. extstat 2024.3.19
            if ( mftal .ge. 5 ) then
               nobchhalf = int( ncurrbch/2 )
             if ( nobchhalf.gt.1 ) then
               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilin
     &         = dble(i)
               yilin
     &         = deist(1,initdeist+(i-1)*sum(itism(1:itnm))+inum)
               sumxi = sumxi + xilin
               sumyi = sumyi + yilin
               sumxyi = sumxyi + xilin*yilin
               sumxi2 = sumxi2 + xilin*xilin
              end do
               slopemean = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )
               slopemean = slopemean
     &         / deist(1,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)

               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
               facls
     &         = deist(2,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &         * dsqrt(dble(ncurrbch))
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilog
     &         = dlog(dble(i))
               yilog
     &         = dlog(deist(2,initdeist+(i-1)*sum(itism(1:itnm))+inum)
     &         / facls )
               sumxi = sumxi + xilog
               sumyi = sumyi + yilog
               sumxyi = sumxyi + xilog*yilog
               sumxi2 = sumxi2 + xilog*xilog
              end do
               powerrele = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )

               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
               facls
     &         = deist(3,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &         * dble(ncurrbch)
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilog
     &         = dlog(dble(i))
               yilog
     &         = dlog(deist(3,initdeist+(i-1)*sum(itism(1:itnm))+inum)
     &         / facls )
               sumxi = sumxi + xilog
               sumyi = sumyi + yilog
               sumxyi = sumxyi + xilog*yilog
               sumxi2 = sumxi2 + xilog*xilog
              end do
               powervov = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )

               sumxi = 0d0
               sumyi = 0d0
               sumxyi = 0d0
               sumxi2 = 0d0
              do i = ncurrbch, ncurrbch-nobchhalf, -1
               xilin
     &         = dble(i)
               yilin
     &         = deist(4,initdeist+(i-1)*sum(itism(1:itnm))+inum)
               sumxi = sumxi + xilin
               sumyi = sumyi + yilin
               sumxyi = sumxyi + xilin*yilin
               sumxi2 = sumxi2 + xilin*xilin
              end do
               slopefom = ( nobchhalf*sumxyi - sumxi*sumyi )
     &             / ( nobchhalf*sumxi2 - sumxi**2 )
               slopefom = slopefom
     &         / deist(4,initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
             else
              slopemean = 0d0
              powerrele = 0d0
              powervov = 0d0
              slopefom = 0d0
             end if
            end if
c S.H. extstat 2024.3.19

c S.H. extstat 2024.3.18
              if ( mftal .gt. 5 ) then
               prodenmn = tr(ip,ie,it,icf(ir,iz),ia,im,6)
               prodenmx = tr(ip,ie,it,icf(ir,iz),ia,im,7)
!$             prodenmn = tprodenmn(m)
!$   &         /(rtfac(m)/vl(ir,iz)/aw(ia)/ew(ie)/tw(it))
!$             prodenmx = tprodenmx(m)
!$   &         /(rtfac(m)/vl(ir,iz)/aw(ia)/ew(ie)/tw(it))
               dproden = dlog(prodenmx/prodenmn) / dble(nproden)
               ntotcnt = 0
               do iproden = 1, nproden
                  ntotcnt = ntotcnt
     &                 + tr(ip,ie,it,icf(ir,iz),ia,im,iproden+8)
               end do

               if ( ntotcnt .gt. 0 ) then
                  do iproden = 1, nproden
                     tr(ip,ie,it,icf(ir,iz),ia,im,iproden+8)
     &                    = tr(ip,ie,it,icf(ir,iz),ia,im,iproden+8)
     &                    /dble(ntotcnt)
                  end do
               end if
              end if
c S.H. extstat 2024.3.18

