     &                     it, eb(ie), eb(ie+1)
               end if
               if( itist(7,m) .gt. 1 ) then
                  write(iot,'(
     &            "#  it =",i3,/
     &            "#   t = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     it, tb(it), tb(it+1)
               end if
               if( itist(9,m) .gt. 1 )
