               if( itist(10,m) .gt. 1 )
     &            write(iot,'("#   mset =",i3)') itmnt(m,im)

c S.H. extstat 2024.4.3
               write(iot,'(/"# Statistical check sheet at batch",i9)')
     &              nobch
               write(iot,'("# Quantity",19x,"Output",21x,"Value",9x,
