     &              deist(1,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               if ( dabs(slopemean) .lt. critpass ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("# Mean",23x,"History dep. (rel. slope)",
     &                   1x,0pf8.4,7x,"= 0.00",5x,a3)')
