               write(iot,'("w: ",1p1e12.4," / x(0.65) y(0.8) f(5)")')
     &              deist(1,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               write(iot,'("w: Constant / x(0.84) y(0.8) f(5)")')

               write(iot,'("w: Mean / x(0.) y(0.7) f(5)")')
