     &              slopemean
               write(iot,'("w: = 0.00 / x(0.84) y(0.7) f(5)")')
               if ( dabs(slopemean) .lt. critpass ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("w: ",a3," / x(0.98) y(0.75) f(5)")') cpass

