               write(iot,'("w: Current value / x(0.33) y(0.6) f(5)")')
               write(iot,'("w: ",0pf8.4," / x(0.65) y(0.6) f(5)")')
     &              deist(2,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               write(iot,'("w: < 0.05 / x(0.84) y(0.6) f(5)")')
               if ( deist(2,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              .lt. 0.05d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
               write(iot,'("w: ",a3," / x(0.98) y(0.6) f(5)")') cpass

               write(iot,'("w: Relative error / x(0.) y(0.5) f(5)")')
               write(iot,'("w: History dep. (p in N^p) "
     &                   ,"/ x(0.33) y(0.5) f(5)")')
               write(iot,'("w: ",0pf8.4," / x(0.65) y(0.5) f(5)")')
     &              powerrele
               write(iot,'("w: = -0.50 / x(0.84) y(0.5) f(5)")')
               if ( dabs(0.5d0+powerrele) .lt. critpass*0.5d0 ) then
                  cpass = cyes
