     &    30     ,    3.79E+01,
     &    40     ,    4.31E+01,
     &    50     ,    4.71E+01,
     &    60     ,    5.01E+01,
     &    80     ,    5.45E+01,
     &    100    ,    5.78E+01,
     &    150    ,    6.33E+01,
     &    200    ,    6.73E+01,
     &    300    ,    7.23E+01,
     &    400    ,    7.55E+01,
     &    500    ,    7.75E+01,
     &    600    ,    7.89E+01,
     &    800    ,    8.05E+01,
     &    1000   ,    8.17E+01,
     &    1500   ,    8.38E+01,
     &    2000   ,    8.52E+01,
     &    3000   ,    8.69E+01,
     &    4000   ,    8.81E+01,
     &    5000   ,    8.89E+01,
     &    6000   ,    8.95E+01,
     &    8000   ,    9.02E+01,
     &    10000  ,    9.07E+01/

      data ((dosc(7,i,j),j=1,2),i=1,in7)/
     &    1      ,   5.46E+00,
     &    1.5    ,   8.20E+00,
     &    2      ,   1.09E+01,
     &    3      ,   1.64E+01,
     &    4      ,   2.19E+01,
     &    5      ,   2.73E+01,
     &    6      ,   3.28E+01,
     &    8      ,   4.37E+01,
     &    10     ,   5.49E+01,
     &    15     ,   1.89E+02,
     &    20     ,   4.28E+02,
     &    30     ,   7.50E+02,
     &    40     ,   1.02E+03,
     &    50     ,   1.18E+03,
     &    60     ,   1.48E+03,
     &    80     ,   2.16E+03,
     &    100    ,   2.51E+03,
     &    150    ,   2.38E+03,
     &    200    ,   1.77E+03,
     &    300    ,   1.38E+03,
     &    400    ,   1.23E+03,
     &    500    ,   1.15E+03,
     &    600    ,   1.16E+03,
     &    800    ,   1.11E+03,
     &    1000   ,   1.09E+03,
     &    1500   ,   1.15E+03,
     &    2000   ,   1.12E+03,
     &    3000   ,   1.23E+03,
     &    4000   ,   1.27E+03,
     &    5000   ,   1.23E+03,
     &    6000   ,   1.37E+03,
     &    8000   ,   1.45E+03,
     &    10000  ,   1.41E+03/

*-----------------------------------------------------------------------

            dosfn = 0.d0

*-----------------------------------------------------------------------

         if( id .eq. 102 ) then

            ip = 1

         else if( id .eq. 114 ) then

            ip = 2

         else if( id .eq. 101 ) then

            ip = 3

         else if( id .eq. 112 ) then

            ip = 4

         else if( id .eq. 1102 ) then

            ip = 5

         else if( id .eq. 1114 ) then

            ip = 6

         else

            return

         end if

*-----------------------------------------------------------------------
*        log-log interpolation for dosc
*      ( lin-lin interpolation )
*-----------------------------------------------------------------------

               if( erg .lt. dosc(ip,1,1) ) then

                  dosfn = dosc(ip,1,2)
                  return

               end if

               do i = 2, inm(ip)

                  if( erg .lt. dosc(ip,i,1) ) goto 100

               end do

                  dosfn = dosc(ip,inm(ip),2)
                  return

  100          continue

                  dosfn = dosc(ip,i-1,2)
     &                  * exp( log( dosc(ip,i,2) / dosc(ip,i-1,2) )
     &                  * log( erg / dosc(ip,i-1,1) )
     &                  / log( dosc(ip,i,1) / dosc(ip,i-1,1) ) )

*-----------------------------------------------------------------------

            if( ip .le. 4 ) dosfn = dosfn / 3.6d-3

*-----------------------------------------------------------------------

      return
      end

************************************************************************
*                                                                      *
      function xlagrange(imode,iclass,xin,cdata)
*                                                                      *
*       a two-four point Lagrange interpolation                        *
*       last modified by N.Matsuda on 2024/12/09                       *
*                                                                      *
************************************************************************

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      integer imode, iclass, iclass0
      dimension cdata(8), ddata(8)
      real*8  xin, yout, cdata, ddata, xlagrange

*-----------------------------------------------------------------------

         iclass0 = 0
         do 100 i = 1, iclass

            if( imode .eq.  1 .or.
     &          imode .eq. -3 .or. imode .eq. -4 ) then

                  iclass0 = iclass0 + 1
                     ddata(4+iclass0) = cdata(4+i)

                  if( imode .eq.  1 ) then
                     ddata(iclass0) = cdata(i)
                  else
                     ddata(iclass0) = log(cdata(i))
                  end if

            else

               if( cdata(i) .le. 0.d0 ) then
               else
                  iclass0 = iclass0 + 1
                     ddata(4+iclass0) = log(cdata(4+i))

                  if( imode .eq.  3 .or. imode .eq.  4 ) then
                     ddata(iclass0) = cdata(i)
                  else
                     ddata(iclass0) = log(cdata(i))
                  end if
               end if

            end if

  100    continue

         if( imode .eq.  1 .or.
     &       imode .eq.  3 .or. imode .eq.  4 ) then
               xin0 = xin
         else
               xin0 = log(xin)
         end if

*-----------------------------------------------------------------------
*     Lagrange:
*-----------------------------------------------------------------------

         yout = 0.d0
         do 200 i = 1, iclass0

            factor = ddata(4+i)
            do 201 j = 1, iclass0

               if( i .ne. j ) then
                  factor = factor * ( xin0 - ddata(j) )
     &                            / ( ddata(i) - ddata(j) )
               end if

  201       continue

            yout = yout + factor

  200    continue

         xlagrange = 0.d0
         if( imode .eq.  1 .or.
     &       imode .eq. -3 .or. imode .eq. -4 ) then
            xlagrange = yout
         else
            xlagrange = exp(yout)
         end if

*-----------------------------------------------------------------------
      return
      end

************************************************************************
*                                                                      *
* sumover subroutine group                                             *
*                                                                      *
************************************************************************
*
************************************************************************
*                                                                      *
      subroutine ttracreg_sumover(m,maxcas,
     &                   np,    ne,    nt,    nr,    nm,    tr0x)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr,nm)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

      if(n_tr_sum > 0) then

        call ttracreg_sumover_sub(maxcas,itaxs(m,iax),
     &     np,    ne,    nt,    nr,    nm,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itrgn_sum(m,iax),itmst_sum(m,iax),tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ttracreg_sumover_sub(maxcas,itaxs_in,
     &                   np,    ne,    nt,    nr,    nm,    tr0,
     &                   np_sum,ne_sum,nt_sum,nr_sum,nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nr,nm)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nm_sum,2)

      if(itaxs_in == 1) then  ! energ
        do im = 1, nm
        do ir = 1, nr
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im) / maxcas
          end do
          tr_sum(ip,1,it,ir,im,1) = tr_sum(ip,1,it,ir,im,1)
     &                            + tr0_sum
          tr_sum(ip,1,it,ir,im,2) = tr_sum(ip,1,it,ir,im,2)
     &                            + tr0_sum ** 2
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 2) then    ! reg
        do im = 1, nm
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ir = 1, nr
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im) / maxcas
          end do
          tr_sum(ip,ie,it,1,im,1) = tr_sum(ip,ie,it,1,im,1)
     &                            + tr0_sum
          tr_sum(ip,ie,it,1,im,2) = tr_sum(ip,ie,it,1,im,2)
     &                            + tr0_sum ** 2
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do im = 1, nm
        do ir = 1, nr
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im) / maxcas
          end do
          tr_sum(ip,ie,1,ir,im,1) = tr_sum(ip,ie,1,ir,im,1)
     &                            + tr0_sum
          tr_sum(ip,ie,1,ir,im,2) = tr_sum(ip,ie,1,ir,im,2)
     &                            + tr0_sum ** 2
        end do
        end do
        end do
        end do

       end if
       return
       end


************************************************************************
*                                                                      *
      subroutine ttracrz_sumover(m,maxcas,
     &                   np, ne, nt, nr, nz, na, nm, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nr*nz,na,nm,2)                                       *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr*nz,na,nm)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call ttracrz_sumover_sub(maxcas,itaxs(m,iax),
     &     np, ne, nt, nr, nz, na, nm,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itrnm_sum(m,iax),itznm_sum(m,iax),itanm_sum(m,iax),
     &     itmst_sum(m,iax),tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ttracrz_sumover_sub(maxcas,itaxs_in,
     &           np, ne, nt, nr, nz, na, nm, tr0,
     &           np_sum, ne_sum, nt_sum, nr_sum, nz_sum,
     &           na_sum, nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nr*nz,na,nm)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum*nz_sum,na_sum,
     &                   nm_sum,2)

      icf(ir,iz) = ir + ( iz - 1 ) * nr
      icf_sum(ir,iz) = ir + ( iz - 1 ) * nr_sum

      if(itaxs_in == 1) then  ! energ
        do im = 1, nm
        do ia = 1, na
        do iz = 1, nz
        do ir = 1, nr
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ir,iz),ia,im) / maxcas
          end do
          tr_sum(ip,1,it,icf_sum(ir,iz),ia,im,1) =
     &           tr_sum(ip,1,it,icf_sum(ir,iz),ia,im,1) + tr0_sum
          tr_sum(ip,1,it,icf_sum(ir,iz),ia,im,2) =
     &          tr_sum(ip,1,it,icf_sum(ir,iz),ia,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 6) then    ! r
        do im = 1, nm
        do ia = 1, na
        do iz = 1, nz
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ir = 1, nr
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ir,iz),ia,im) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(1,iz),ia,im,1) =
     &           tr_sum(ip,ie,it,icf_sum(1,iz),ia,im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(1,iz),ia,im,2) =
     &          tr_sum(ip,ie,it,icf_sum(1,iz),ia,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do


      elseif(itaxs_in == 5) then    ! z
        do im = 1, nm
        do ia = 1, na
        do ir = 1, nr
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iz = 1, nz
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ir,iz),ia,im) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ir,1),ia,im,1) =
     &           tr_sum(ip,ie,it,icf_sum(ir,1),ia,im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(ir,1),ia,im,2) =
     &          tr_sum(ip,ie,it,icf_sum(ir,1),ia,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do im = 1, nm
        do ia = 1, na
        do iz = 1, nz
        do ir = 1, nr
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ir,iz),ia,im) / maxcas
          end do
          tr_sum(ip,ie,1,icf_sum(ir,iz),ia,im,1) =
     &           tr_sum(ip,ie,1,icf_sum(ir,iz),ia,im,1) + tr0_sum
          tr_sum(ip,ie,1,icf_sum(ir,iz),ia,im,2) =
     &          tr_sum(ip,ie,1,icf_sum(ir,iz),ia,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 12 .or. itaxs_in == 13) then   ! ang
        do im = 1, nm
        do iz = 1, nz
        do ir = 1, nr
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ia = 1, na
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ir,iz),ia,im) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ir,iz),1,im,1) =
     &           tr_sum(ip,ie,it,icf_sum(ir,iz),1,im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(ir,iz),1,im,2) =
     &          tr_sum(ip,ie,it,icf_sum(ir,iz),1,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine ttracxyz_sumover(m,maxcas,
     &                   np, ne, nt, nx, ny, nz, nm, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nx*ny*nz,nm,2)                                   *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nx*ny*nz,nm)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call ttracxyz_sumover_sub(maxcas,itaxs(m,iax),
     &     np, ne, nt, nx, ny, nz, nm, tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &     itmst_sum(m,iax),tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ttracxyz_sumover_sub(maxcas,itaxs_in,
     &           np, ne, nt, nx, ny, nz, nm, tr0,
     &           np_sum, ne_sum, nt_sum, nx_sum, ny_sum, nz_sum, nm_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nx*ny*nz,nm)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nx_sum*ny_sum*nz_sum,
     &                   nm_sum,2)

      icf(ix,iy,iz) = ix + ( iy - 1 ) * nx + ( iz - 1 ) * nx * ny
      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                  + ( iz - 1 ) * nx_sum * ny_sum

      if(itaxs_in == 1) then  ! energ
        do im = 1, nm
        do iz = 1, nz
        do iy = 1, ny
        do ix = 1, nx
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im) / maxcas
          end do
          tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,1) =
     &           tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,1) + tr0_sum
          tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,2) =
     &          tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 3) then    ! x
        do im = 1, nm
        do iz = 1, nz
        do iy = 1, ny
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ix = 1, nx
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,1) =
     &           tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,2) =
     &           tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 4) then    ! y
        do im = 1, nm
        do iz = 1, nz
        do ix = 1, nx
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iy = 1, ny
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,1) =
     &           tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,2) =
     &           tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 5) then    ! z
        do im = 1, nm
        do iy = 1, ny
        do ix = 1, nx
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iz = 1, nz
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im) / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,1) =
     &           tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,2) =
     &           tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do im = 1, nm
        do iz = 1, nz
        do iy = 1, ny
        do ix = 1, nx
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im) / maxcas
          end do
          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,1) =
     &           tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,1) + tr0_sum
          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,2) =
     &          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

       end if
       return
       end

