************************************************************************
*                                                                      *
      subroutine thetreg_sumover_sub(maxcas,itaxs_in,
     &                   nd,    nr,    ne,  tr0,
     &                   nd_sum,nr_sum,ne_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(nd,nr,0:ne)
      dimension   tr_sum(nd_sum,nr_sum,0:ne_sum,2)

      if(itaxs_in == 1) then  ! energ
        do ir = 1, nr
        do id = 1, nd
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(id,ir,ie) / maxcas
          end do
          tr_sum(id,ir,1,1) = tr_sum(id,ir,1,1)
     &                            + tr0_sum
          tr_sum(id,ir,1,2) = tr_sum(id,ir,1,2)
     &                            + tr0_sum ** 2

          tr_sum(id,ir,0,1) =  tr0(id,ir,0) / maxcas
          tr_sum(id,ir,0,2) = (tr0(id,ir,0) / maxcas) ** 2
        end do
        end do
!
      elseif(itaxs_in == 2) then    ! reg
        do ie = 0, ne
        do id = 1, nd
          tr0_sum = 0.0d0
          do ir = 1, nr
            tr0_sum = tr0_sum + tr0(id,ir,ie) / maxcas
          end do
          tr_sum(id,1,ie,1) = tr_sum(id,1,ie,1)
     &                            + tr0_sum
          tr_sum(id,1,ie,2) = tr_sum(id,1,ie,2)
     &                            + tr0_sum ** 2
        end do
        end do

       end if
       return
       end

