        do ie = 0, ne
        do iz = 1, nz
        do ix = 1, nx
        do id = 1, nd
          tr0_sum = 0.0d0
          do iy = 1, ny
            tr0_sum = tr0_sum + tr0(id,ix,iy,iz,ie) / maxcas
          end do
