************************************************************************
*                                                                      *
      subroutine ptracreg_sumover_stdev(mode,m,ip,ie,it,ir,im,
     &                fact_in,ew,tw,vl,ew_sum,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

        else

          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

        endif

        if(n_tr_sum > 0) then

          sum_fact = fact_in/vl/ew/tw

          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call ptracreg_sumover_stdev_sub(mode,m,sum_fact,
     &           ip,ie,it,ir,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrgn_sum(m,iax),itmst_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ptracreg_sumover_stdev_ntf(mode,m,ntf,ip,ie,it,ir,im,
     &                fact_in,ew,tw,vl,ew_sum,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if

        else

          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)

        endif

        if(n_tr_sum > 0) then

          sum_fact = fact_in/vl/ew/tw

          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call ptracreg_sumover_stdev_sub(mode,m,sum_fact,
     &           ip,ie,it,ir,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrgn_sum(m,iax),itmst_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine ptracreg_sumover_stdev_sub(mode,m,sum_fact,
     &           ip,ie,it,ir,im,
     &           np_sum,ne_sum,nt_sum,nr_sum,nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nm_sum,2)

      if(tr_sum(ip,ie,it,ir,im,1) > 0.0) then

        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                    tr_sum(ip,ie,it,ir,im,1),
     &                    tr_sum(ip,ie,it,ir,im,2),
     &                    sum_fact)
        else

          sum_fact_r = 1.0d0 / sum_fact

          call invert_stdev(m,Xa,sigx,
     &                    tr_sum(ip,ie,it,ir,im,1),
     &                    tr_sum(ip,ie,it,ir,im,2),
     &                    sum_fact_r)
        endif

        tr_sum(ip,ie,it,ir,im,1) = Xa
        tr_sum(ip,ie,it,ir,im,2) = sigx

      else

        tr_sum(ip,ie,it,ir,im,2) = 0.0

