            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

        call ptracreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nmstepi,
