************************************************************************
*                                                                      *
      subroutine ptracreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nmstepi,
     &    ipi,iei,iti,iri,imi,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nr_sum,nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nm_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
        do imloop=1,nmstepi
          do irloop=1,nrstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,
     &                iti+itloop-1,iri+irloop-1,
     &                imi+imloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,
     &                     iti+itloop-1,iri+irloop-1,
     &                     imi+imloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do
        end do

      return
      end


************************************************************************
*                                                                      *
      subroutine ptracrz_sumover_stdev(mode,m,ip,ie,it,ir,iz,ia,im,
     &                fact_in,ew,tw,vl,aw,ew_sum,tw_sum,
     &                vl_r,vl_z,aw_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

       else

          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/ew/tw/vl/aw
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else if(itaxs(m,iax) == 6 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_r
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else if((itaxs(m,iax) == 12 .or. itaxs(m,iax) == 13) .and.
     &             ia == 1) then
             sum_fact = sum_fact * aw / aw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call ptracrz_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ir,iz,ia,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrnm_sum(m,iax),itznm_sum(m,iax),itanm_sum(m,iax),
     &         itmst_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

