************************************************************************
*                                                                      *
      subroutine ptracrz_sumover_stdev_sub(mode,m,sum_fact,
     &                   ip,ie,it,ir,iz,ia,im,
     &                   np_sum,ne_sum,nt_sum,nr_sum,nz_sum,na_sum,
     &                   nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum*nz_sum,na_sum,
     &                   nm_sum,2)
         icf_sum(ir,iz) = ir + ( iz - 1 ) * nr_sum


      if(tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,1) > 0.0) then
        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,1),
     &                  tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,2),
     &                  sum_fact)
        else
          sum_fact_r = 1.0d0 / sum_fact
          call invert_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,1),
     &                  tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,2),
     &                  sum_fact_r)
        endif

        tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,1) = Xa
        tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,2) = sigx

      else

        tr_sum(ip,ie,it,icf_sum(ir,iz),ia,im,2) = 0.0

      end if

      return
      end


