        call ptracrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nzstepi,nastepi,nmstepi,
     &    ipi,iei,iti,iri,izi,iai,imi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itrnm_sum(m,iax),itznm_sum(m,iax),itanm_sum(m,iax),
     &    itmst_sum(m,iax),tr_sum)

      else

        tr_sum => trRES_sum(irestalm_sum(m,iax):)

        nsame = npstepi * nestepi * ntstepi * nrstepi * nzstepi
     &        * nastepi * nmstepi
        allocate(tott_in(nsame,2))

        read(mode,'(a)') chin
        read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &     (tott_in(i,1),tott_in(i,2),i=1,nsame)

        call ptracrz_sumover_getput_sub(mode,
