************************************************************************
*                                                                      *
      subroutine ptracrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nzstepi,nastepi,nmstepi,
     &    ipi,iei,iti,iri,izi,iai,imi,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nr_sum,nz_sum,na_sum,nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nt_sum,nr_sum*nz_sum,na_sum,
     &                  nm_sum,2)

      real(8) :: tott_sum(maxtott,2)

      icf_sum(ir,iz) = ir + ( iz - 1 ) * nr_sum

        i = 0
        do imloop=1,nmstepi
         do ialoop=1,nastepi
          do izloop=1,nzstepi
           do irloop=1,nrstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,
     &                iti+itloop-1,
     &                icf_sum(iri+irloop-1,izi+izloop-1),
     &                iai+ialoop-1,imi+imloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,
     &                       iti+itloop-1,
     &                       icf_sum(iri+irloop-1,izi+izloop-1),
     &                       iai+ialoop-1,imi+imloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do
        end do
       end do
      end do

      return
      end

