************************************************************************
*                                                                      *
      subroutine phetreg_sumover_stdev_sub(mode,m,sum_fact,ik,ir,ie,
     &                   nd_sum,nr_sum,ne_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(nd_sum,nr_sum, 0:ne_sum,2)

      if(tr_sum(ik,ir,ie,1) > 0.0) then
        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                  tr_sum(ik,ir,ie,1),
     &                  tr_sum(ik,ir,ie,2),
     &                  sum_fact)
        else
          sum_fact_r = 1.0d0 / sum_fact
          call invert_stdev(m,Xa,sigx,
     &                  tr_sum(ik,ir,ie,1),
     &                  tr_sum(ik,ir,ie,2),
     &                  sum_fact_r)
        endif

        tr_sum(ik,ir,ie,1) = Xa
        tr_sum(ik,ir,ie,2) = sigx

      else

        tr_sum(ik,ir,ie,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  phetreg_sumover_get(m,iax,
     &    kl,ks,np,itype_het,
     &    idd,ir,ie,maxtott_n,tott_n)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)

      real(8) :: tott_n(maxtott_n,2)

      dimension kl(7,7)
      dimension ks(7)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

      call phetreg_sumover_get_sub(
     &    kl,ks,np,itype_het,
     &    idd,ir,ie,maxtott_n,tott_n,
     &    itndy_sum(m,iax),itrgn_sum(m,iax),itenm_sum(m,iax),
     &    tr_sum)

      return
      end

************************************************************************
*                                                                      *
      subroutine phetreg_sumover_get_sub(
     &    kl,ks,np,itype_het,
     &    idd,ir,ie,maxtott_n,tott_n,
     &    nd_sum,nr_sum,ne_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(nd_sum,nr_sum,0:ne_sum,2)

      real(8) :: tott_n(maxtott_n,2)

      dimension kl(7,7)
      dimension ks(7)

      do j=1,2

        if(itype_het == 1) then
          do k = 1, ks(idd)
            tott_n(k,j) = tr_sum(kl(idd,k),ir,ie,j)
          end do
        else if(itype_het == 2) then
          tott_n(1,j) = tr_sum(7,ir,ie,j)
          do k=1,np
            tott_n(k+1,j) = tr_sum(29+k,ir,ie,j)
          enddo
        else if(itype_het == 3) then
          tott_n(1,j) = tr_sum(11,ir,ie,j)
          do k=1,np
            tott_n(k+1,j) = tr_sum(29+np+k,ir,ie,j)
          enddo
        endif

      enddo

      return
      end


************************************************************************
