     &         ik,ir,iz,ie,
     &         itndy_sum(m,iax),itrnm_sum(m,iax),itznm_sum(m,iax),
     &         itenm_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine phetrz_sumover_stdev_sub(mode,m,sum_fact,ik,ir,iz,ie,
     &                   nd_sum,nr_sum,nz_sum,ne_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(nd_sum,nr_sum,nz_sum,0:ne_sum,2)

      if(tr_sum(ik,ir,iz,ie,1) > 0.0) then
        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                  tr_sum(ik,ir,iz,ie,1),
     &                  tr_sum(ik,ir,iz,ie,2),
     &                  sum_fact)
        else
          call invert_stdev(m,Xa,sigx,
     &                  tr_sum(ik,ir,iz,ie,1),
     &                  tr_sum(ik,ir,iz,ie,2),
     &                  sum_fact)
        endif

        tr_sum(ik,ir,iz,ie,1) = Xa
        tr_sum(ik,ir,iz,ie,2) = sigx

      else

        tr_sum(ik,ir,iz,ie,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  phetrz_sumover_get(m,iax,
     &    kl,ks,np,itype_het,
     &    idd,ir,iz,ie,maxtott_n,tott_n)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)

      real(8) :: tott_n(maxtott_n,2)

      dimension kl(7,7)
      dimension ks(7)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

      call phetrz_sumover_get_sub(
     &    kl,ks,np,itype_het,
     &    idd,ir,iz,ie,maxtott_n,tott_n,
     &    itndy_sum(m,iax),itrnm_sum(m,iax),itznm_sum(m,iax),
     &    itenm_sum(m,iax),
     &    tr_sum)

      return
      end

************************************************************************
*                                                                      *
      subroutine phetrz_sumover_get_sub(
     &    kl,ks,np,itype_het,
     &    idd,ir,iz,ie,maxtott_n,tott_n,
     &    nd_sum,nr_sum,nz_sum,ne_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(nd_sum,nr_sum,nz_sum,0:ne_sum,2)

      real(8) :: tott_n(maxtott_n,2)

      dimension kl(7,7)
      dimension ks(7)

      do j=1,2

        if(itype_het == 1) then
          do k = 1, ks(idd)
            tott_n(k,j) = tr_sum(kl(idd,k),ir,iz,ie,j)
          end do
        else if(itype_het == 2) then
          tott_n(1,j) = tr_sum(7,ir,iz,ie,j)
          do k=1,np
            tott_n(k+1,j) = tr_sum(29+k,ir,iz,ie,j)
          enddo
        else if(itype_het == 3) then
          tott_n(1,j) = tr_sum(11,ir,iz,ie,j)
          do k=1,np
            tott_n(k+1,j) = tr_sum(29+np+k,ir,iz,ie,j)
          enddo
        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine phetxyz_sumover_stdev(mode,m,ik,ix,iy,iz,ie,
     &                fact_in,vl,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

        else

          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

        endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl
          if(itaxs(m,iax) == 1 .and. ie == 1) then

          else if(itaxs(m,iax) == 3 .and. ix == 1) then
            sum_fact = sum_fact * vl / vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
            sum_fact = sum_fact * vl / vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
            sum_fact = sum_fact * vl / vl_z
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call phetxyz_sumover_stdev_sub(mode,m,sum_fact,
     &         ik,ix,iy,iz,ie,
     &         itndy_sum(m,iax),itxnm_sum(m,iax),itynm_sum(m,iax),
     &         itznm_sum(m,iax),itenm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine phetxyz_sumover_stdev_ntf(mode,m,ntf,ik,ix,iy,iz,ie,
     &                fact_in,vl,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if

        else

          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)

        endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl
          if(itaxs(m,iax) == 1 .and. ie == 1) then

          else if(itaxs(m,iax) == 3 .and. ix == 1) then
            sum_fact = sum_fact * vl / vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
            sum_fact = sum_fact * vl / vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
            sum_fact = sum_fact * vl / vl_z
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call phetxyz_sumover_stdev_sub(mode,m,sum_fact,
     &         ik,ix,iy,iz,ie,
     &         itndy_sum(m,iax),itxnm_sum(m,iax),itynm_sum(m,iax),
     &         itznm_sum(m,iax),itenm_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine phetxyz_sumover_stdev_sub(mode,m,sum_fact,
     &                   ik,ix,iy,iz,ie,
     &                   nd_sum,nx_sum,ny_sum,nz_sum,ne_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(nd_sum,nx_sum,ny_sum,nz_sum, 0:ne_sum,2)

      if(tr_sum(ik,ix,iy,iz,ie,1) > 0.0) then
        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                  tr_sum(ik,ix,iy,iz,ie,1),
     &                  tr_sum(ik,ix,iy,iz,ie,2),
     &                  sum_fact)
        else
          sum_fact_r = 1.0d0 / sum_fact
          call invert_stdev(m,Xa,sigx,
     &                  tr_sum(ik,ix,iy,iz,ie,1),
     &                  tr_sum(ik,ix,iy,iz,ie,2),
     &                  sum_fact_r)
        endif

        tr_sum(ik,ix,iy,iz,ie,1) = Xa
        tr_sum(ik,ix,iy,iz,ie,2) = sigx

      else

        tr_sum(ik,ix,iy,iz,ie,2) = 0.0

      end if

      return
      end

